BEGIN;
SET search_path TO public;

-- Preguntas 2101 a 2200
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2101, 'SUB-2101', 'SBM4', 'EL QUE, MEDIANTE VIOLENCIA, AMENAZA U OTRO MEDIO OBLIGA A UNA PERSONA A EJERCER ACTOS DE CONNOTACIÓN SEXUAL CON LA FINALIDAD DE OBTENER UN APROVECHAMIENTO ECONÓMICO O DE OTRA ÍNDOLE, COMETE DELITO DE:.', 'EXPLOTACIÓN SEXUAL.', 'ART. 129 - C', '184246'),
    (2102, 'SUB-2102', 'SBM4', 'EL QUE OBLIGA A UNA PERSONA A TRABAJAR EN CONDICIONES DE ESCLAVITUD O SERVIDUMBRE, O LA REDUCE O MANTIENE EN DICHAS CONDICIONES, CON EXCEPCION DE LOS SUPUESTOS DEL DELITO DE EXPLOTACION SEXUAL, COMETE DELITO DE:.', 'ESCLAVITUD Y OTRAS FORMAS DE EXPLOTACION.', 'ART. 153 - C', '184247'),
    (2103, 'SUB-2103', 'SBM4', 'EL QUE SIN DERECHO, PENETRA EN MORADA O CASA DE NEGOCIO AJENA, EN SU DEPENDENCIA O EN EL RECINTO HABITADO POR OTRO O EL QUE PERMANECE ALLI REHUSANDO LA INTIMACION QUE LE HAGA QUIEN TENGA DERECHO A FORMULARLA, COMETE DELITO DE:.', 'VIOLACION DE DOMICILIO.', 'ART. 159', '184248'),
    (2104, 'SUB-2104', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PUBLICO QUE ALLANA UN DOMICILIO, SIN LAS FORMALIDADES PRESCRITAS POR LA LEY O FUERA DE LOS CASOS QUE ELLA DETERMINA, COMETE DELITO DE:.', 'ALLANAMIENTO ILEGAL DE DOMICILIO.', 'ART. 160 Código Penal', '184249'),
    (2105, 'SUB-2105', 'SBM4', 'EL QUE INDEBIDAMENTE, INTERVIENE O INTERFIERE O ESCUCHA UNA CONVERSACION TELEFONICA O SIMILAR, COMETE DELITO DE:.', 'INTERFERENCIA TELEFONICA.', 'ART. 162', '184250'),
    (2106, 'SUB-2106', 'SBM4', '. EL QUE PARA OBTENER PROVECHO, SE APODERA ILEGITIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, SUSTRAYENDOLO DEL LUGAR DONDE SE ENCUENTRA, COMETE DELITO DE:.', 'HURTO SIMPLE.', 'ART. 185', '184251'),
    (2107, 'SUB-2107', 'SBM4', 'EL QUE PARA OBTENER PROVECHO, SE APODERA ILEGITIMAMENTE DE UN BIEN MUEBLE, TOTAL O PARCIALMENTE AJENO, SUSTRAYENDOLO DEL LUGAR DONDE SE ENCUENTRA, MEDIANTE DESTREZA, ESCALAMIENTO, ROTURA DE OBSTACULOS, COMETE DELITO DE:.', 'HURTO AGRAVADO.', 'ART. 186', '184252'),
    (2108, 'SUB-2108', 'SBM4', 'EL QUE SE APODERA ILEGÍTIMAMENTE DE UN BIEN MUEBLE TOTAL O PARCIALMENTE AJENO, PARA APROVECHARSE DE ÉL, SUSTRAYÉNDOLO DEL LUGAR EN QUE SE ENCUENTRA, EMPLEANDO VIOLENCIA CONTRA LA PERSONA O AMENAZÁNDOLA CON UN PELIGRO INMINENTE PARA SU VIDA O INTEGRIDAD FÍSICA, COMETE DELITO DE:', 'ROBO.', 'ART. 188', '184253'),
    (2109, 'SUB-2109', 'SBM4', 'EL QUE SE APODERA ILEGITIMAMENTE DE UN BIEN MUEBLE TOTAL O PARCIALMENTE, PARA APROVECHARSE DE EL, SUSTRAYENDOLO DEL LUGAR EN QUE SE ENCUENTRA, EMPLEANDO VIOLENCIA CONTRA LA PERSONA O AMENAZANDOLA CON UN PELIGRO INMINENTE PARA SU VIDA O INTEGRIDAD FISICA, CON EL CONCURSO DE DOS O MAS PERSONAS, QUE DELITO COMETE:.', 'ROBO AGRAVADO.', 'ART. 189', '184254'),
    (2110, 'SUB-2110', 'SBM4', 'EL QUE, EN SU PROVECHO O DE UN TERCERO, SE APROPIA INDEBIDAMENTE DE UN BIEN MUEBLE, UNA SUMA DE DINERO O UN VALOR QUE HA RECIBIDO EN DEPÓSITO, COMISIÓN, ADMINISTRACIÓN U OTRO TÍTULO SEMEJANTE QUE PRODUZCA OBLIGACIÓN DE ENTREGAR, DEVOLVER, O HACER UN USO DETERMINADO, COMETE DELITO DE:', 'APROPIACION ILICITA.', 'ART. 190', '184255'),
    (2111, 'SUB-2111', 'SBM4', 'EL QUE ADQUIERE, RECIBE EN DONACIÓN, EN PRENDA, GUARDA, ESCONDE, EXPONE PARA LA VENTA, AYUDA A NEGOCIAR, COMERCIALIZA, DESENSAMBLA O UTILIZA, UN BIEN O SUS PARTES DE CUYA PROCEDENCIA DELICTUOSA TENÍA CONOCIMIENTO O DEBÍA PRESUMIR QUE PROVENÍA DE UN DELITO, COMETE DELITO DE:', 'RECEPTACION.', 'ART. 194', '184256'),
    (2112, 'SUB-2112', 'SBM4', 'EL QUE ENCONTRANDOSE EN ESTADO DE EBRIEDAD, CON PRESENCIA DE ALCOHOL EN LA SANGRE EN PROPORCION MAYOR DE 0.5 GRAMOS-LITRO, O BAJO EL EFECTO DE DROGAS TOXICAS, ESTUPEFACIENTES, SUSTANCIAS PSICOTROPICAS O SINTETICAS, CONDUCE, OPERA O MANIOBRA, VEHICULO MOTORIZADO, COMETE DELITO DE:.', 'CONDUCCION EN ESTADO DE EBRIEDAD O DROGADICCION.', 'ART. 274', '184257'),
    (2113, 'SUB-2113', 'SBM4', 'EL QUE SUSTRAE O ARREBATE ARMAS DE FUEGO EN GENERAL, O MUNICIONES Y GRANADAS DE GUERRA O EXPLOSIVOS A MIEMBROS DE LAS FUERZAS ARMADAS O DE LA POLICIA NACIONAL O DE SERVICIOS DE SEGURIDAD, COMETE DELITO DE:.', 'SUSTRACCION O ARREBATO DE ARMAS DE FUEGO.', 'ART. 279 - B', '184258'),
    (2114, 'SUB-2114', 'SBM4', '. EL QUE CON VIOLENCIA, FISICA O PSICOLOGICA, GRAVE AMENAZA O APROVECHANDOSE DE UN ENTORNO DE COACCION O DE CUALQUIER OTRO ENTORNO QUE IMPIDA A LA PERSONA DAR SU LIBRE CONSENTIMIENTO, OBLIGA A ESTA A TENER ACCESO CARNAL POR VIA VAGINAL, ANAL O BUCAL O REALIZA CUALQUIER OTRO ACTO ANALOGO CON LA INTRODUCCION DE UN OBJETO O PARTE DEL CUERPO POR ALGUNA DE LAS DOS PRIMERAS VIAS, COMETE DELITO DE:.', 'VIOLACION SEXUAL.', 'ART. 170', '184259'),
    (2115, 'SUB-2115', 'SBM4', 'EL QUE, MEDIANTE ENGAÑO TIENE ACCESO CARNAL POR VÍA VAGINAL, ANAL O BUCAL O REALIZA CUALQUIER OTRO ACTO ANÁLOGO CON LA INTRODUCCIÓN DE UN OBJETO O PARTE DEL CUERPO POR ALGUNA DE LAS DOS PRIMERAS VÍAS, A UNA PERSONA DE CATORCE AÑOS Y MENOS DE DIECIOCHO AÑOS, COMETE DELITO DE:', 'VIOLACION SEXUAL MEDIANTE ENGAÑO.', 'ART. 175', '184260'),
    (2116, 'SUB-2116', 'SBM4', 'EL FUNCIONARIO PUBLICO QUE ABUSANDO DE SUS ATRIBUCIONES, COMETE U ORDENA UN ACTO ARBITRARIO QUE CAUSE PERJUICIO A ALGUIEN, COMETE DELITO DE:.', 'ABUSO DE AUTORIDAD.', 'ART. 376', '184262'),
    (2117, 'SUB-2117', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PUBLICO QUE ABUSANDO DE SU CARGO, OBLIGA O INDUCE A UNA PERSONA A DAR O PROMETER INDEBIDAMENTE, PARA SI O PARA OTRO, UN BIEN O UN BENEFICIO PATRIMONIAL, COMETE DELITO DE:.', 'CONCUSION.', 'ART. 382', '184263'),
    (2118, 'SUB-2118', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PUBLICO QUE SE APROPIA O UTILIZA EN CUALQUIER FORMA, PARA SI O PARA OTRO, CAUDALES O EFECTOS CUYA PERCEPCION, ADMINISTRACION O CUSTODIA LE ESTEN CONFIADOS, POR RAZON DE SU CARGO, COMETE DELITO DE:.', 'PECULADO.', 'ART. 387', '184264'),
    (2119, 'SUB-2119', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PUBLICO QUE DA AL DINERO O BIENES QUE ADMINISTRA UNA APLICACION DEFINITIVA DIFERENTE DE AQUELLA A LOS QUE ESTAN DESTINADOS, AFECTANDO EL SERVICIO O LA FUNCION ENCOMENDADA, COMETE DELITO DE:.', 'MALVERSACION.', 'ART. 389', '184265'),
    (2120, 'SUB-2120', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PUBLICO QUE ACEPTE O RECIBA DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, PARA REALIZAR U OMITIR UN ACTO EN VIOLACION DE SUS OBLIGACIONES O EL QUE LAS ACEPTA A CONSECUENCIA DE HABER FALTADO A ELLAS, COMETE DELITO DE:.', 'COHECHO PASIVO PROPIO.', 'ART. 393', '184266'),
    (2121, 'SUB-2121', 'SBM4', 'EL FUNCIONARIO O SERVIDOR PÚBLICO QUE ACEPTE O RECIBA DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO INDEBIDO PARA REALIZAR UN ACTO PROPIO DE SU CARGO O EMPLEO, SIN FALTAR A SU OBLIGACIÓN, O COMO CONSECUENCIA DEL YA REALIZADO, COMETE DELITO DE:', 'COHECHO PASIVO IMPROPIO.', 'ART. 394', '184267'),
    (2122, 'SUB-2122', 'SBM4', 'EL MIEMBRO DE LA POLICIA NACIONAL QUE ACEPTA O RECIBE DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO, PARA SI O PARA OTRO, PARA REALIZAR U OMITIR UN ACTO EN VIOLACION DE SUS OBLIGACIONES DERIVADAS DE LA FUNCION POLICIAL O EL QUE LAS ACEPTA A CONSECUENCIA DE HABER FALTADO A ELLAS, COMETE DELITO DE:.', 'COHECHO PASIVO PROPIO EN EL EJERCICIO DE LA FUNCION POLICIAL.', 'ART. 395 - A', '184268'),
    (2123, 'SUB-2123', 'SBM4', 'EL MIEMBRO DE LA POLICÍA NACIONAL O DEL SISTEMA PENITENCIARIO QUE ACEPTE O RECIBE DONATIVO, PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO INDEBIDO PARA REALIZAR U OMITIR UN ACTO PROPIO DE SU FUNCIÓN, SIN FALTAR A SU OBLIGACIÓN, O COMO CONSECUENCIA DEL ACTO YA REALIZADO U OMITIDO, COMETE DELITO DE:', 'COHECHO PASIVO IMPROPIO EN EL EJERCICIO DE LA FUNCION POLICIAL.', 'ART. 395 - B', '184269'),
    (2124, 'SUB-2124', 'SBM4', 'EL QUE, INVOCANDO O TENIENDO INFLUENCIAS REALES O SIMULADAS, RECIBE, HACE DAR O PROMETER PARA SÍ O PARA UN TERCERO, DONATIVO O PROMESA O CUALQUIER OTRA VENTAJA O BENEFICIO CON EL OFRECIMIENTO DE INTERCEDER ANTE UN FUNCIONARIO O SERVIDOR PÚBLICO QUE HA DE CONOCER, ESTÉ CONOCIENDO O HAYA CONOCIDO UN CASO JUDICIAL O ADMINISTRATIVO, COMETE DELITO DE:', 'TRAFICO DE INFLUENCIAS.', 'ART. 400', '184270'),
    (2125, 'SUB-2125', 'SBM4', '. EL QUE MEDIANTE EL USO DE LA FUERZA FISICA, AMENAZA, OFRECIMIENTO O CONCESION DE UN BENEFICIO INDEBIDO, IMPIDE U OBSTACULIZA SE PRESTE UN TESTIMONIO O LA APORTACION DE PRUEBAS O INDUCE A QUE SE PRESTE UN FALSO TESTIMONIO O PRUEBAS FALSAS, COMETE DELITO DE:', 'OBSTRUCCION DE LA JUSTICIA.', 'ART. 409 - A', '184271'),
    (2126, 'SUB-2126', 'SBM4', 'EL QUE INSERTA O HACE INSERTAR EN INSTRUMENTO PÚBLICO, DECLARACIONES FALSAS, CONCERNIENTES A HECHOS QUE DEBAN PROBARSE CON EL DOCUMENTO, CON EL OBJETO DE EMPLEARLO COMO SI LA DECLARACIÓN FUERA CONFORME A LA VERDAD, SI DE SU USO PUEDE RESULTAR ALGÚN PERJUICIO, COMETE DELITO:', 'FALSEDAD IDEOLOGICA.', 'ART. 428', '184272'),
    (2127, 'SUB-2127', 'SBM4', '¿CUÁL DE LOS SIGUIENTES SUPUESTOS EXIME DE LA RESPONSABILIDAD PENAL POR ANOMALÍA PSÍQUICA DE ACUERDO AL ARTÍCULO 20 DEL CÓDIGO PENAL?:', 'EL QUE POR ANOMALÍA PSÍQUICA O GRAVE ALTERACIÓN DE LA CONCIENCIA, QUE AFECTAN GRAVEMENTE SU CONCEPTO DE LA REALIDAD, NO POSEA LA FACULTAD DE COMPRENDER EL CARÁCTER DELICTUOSO DE SU ACTO O PARA DETERMINARSE SEGÚN ESTA COMPRENSIÓN.', 'ART. 20', '184273'),
    (2128, 'SUB-2128', 'SBM4', 'RESPECTO AL USO DE LA FUERZA LETAL EN DEFENSA DE BIENES JURÍDICOS, SEÑALE LA ALTERNATIVA CORRECTA SEGÚN EL ARTÍCULO 20 DEL CÓDIGO PENAL:', 'DEBE EXISTIR AGRESIÓN ILEGÍTIMA, REAL Y ACTUAL; NECESIDAD RACIONAL DEL MEDIO EMPLEADO Y AUSENCIA DE PROVOCACIÓN SUFICIENTE.', 'ART. 20', '184274'),
    (2129, 'SUB-2129', 'SBM4', 'EN RELACIÓN A LA EXENCIÓN DE RESPONSABILIDAD PENAL POR ESTADO DE NECESIDAD, SEGÚN EL ARTÍCULO 20, ¿CUÁL ES LA PREMISA ESENCIAL PARA LA APLICACIÓN DE ESTA CAUSA JUSTIFICANTE:', 'EL BIEN JURÍDICO PROTEGIDO DEBE SER PREDOMINANTE SOBRE EL INTERÉS DAÑADO Y EL MEDIO EMPLEADO DEBE SER ADECUADO PARA CONJURAR EL PELIGRO.', 'ART. 20', '184275'),
    (2130, 'SUB-2130', 'SBM4', '¿EN QUÉ SUPUESTO NO PROCEDERÁ LA EXENCIÓN DE RESPONSABILIDAD PENAL POR ESTADO DE NECESIDAD EXCULPANTE, CONFORME AL ARTÍCULO 20 DEL CÓDIGO PENAL:', 'CUANDO EL PELIGRO PROVIENE DE ACTO PROPIO DEL AGENTE', 'ART. 20', '184276'),
    (2131, 'SUB-2131', 'SBM4', 'CONFORME AL ARTÍCULO 20 DEL CÓDIGO PENAL, ¿EL CONSENTIMIENTO VÁLIDO DEL TITULAR DE UN BIEN JURÍDICO DE LIBRE DISPOSICIÓN EXIME DE RESPONSABILIDAD PENAL CUANDO:', 'EL CONSENTIMIENTO ES OTORGADO VÁLIDAMENTE, EL TITULAR ES CAPAZ Y EL BIEN JURÍDICO ES DE LIBRE DISPOSICIÓN.', 'ART. 20', '184277'),
    (2132, 'SUB-2132', 'SBM4', '¿CUÁL ES EL CRITERIO QUE SE REEMPLAZA PARA VALORAR LA RACIONALIDAD DEL MEDIO DE DEFENSA SEGÚN EL ARTÍCULO 20 DEL CÓDIGO PENAL:', 'EL DE PROPORCIONALIDAD DE MEDIOS, SIENDO SUSTITUIDO POR LA VALORACIÓN DE LA INTENSIDAD Y PELIGROSIDAD DE LA AGRESIÓN, FORMA DE PROCEDER DEL AGRESOR Y MEDIOS DISPONIBLES PARA LA DEFENSA.', 'ART. 20', '184278'),
    (2133, 'SUB-2133', 'SBM4', 'SEGÚN EL ARTÍCULO 20 DEL CÓDIGO PENAL, ¿QUIÉNES PUEDEN INVOCAR LA EXENCIÓN DE RESPONSABILIDAD PENAL POR DEFENDER UN INMUEBLE ILEGÍTIMAMENTE OCUPADO:', 'EL POSEEDOR LEGÍTIMO Y SUS PARIENTES HASTA EL TERCER GRADO DE CONSANGUINIDAD O DE AFINIDAD PRESENTES EN EL INMUEBLE.', 'ART. 20', '184279'),
    (2134, 'SUB-2134', 'SBM4', '¿QUÉ SUCEDE SI UNA PERSONA ACTÚA POR MIEDO INSUPERABLE DE UN MAL IGUAL O MAYOR, SEGÚN EL ARTÍCULO 20 DEL CÓDIGO PENAL:', 'SE LE EXIME DE RESPONSABILIDAD PENAL.', 'ART. 20', '184280'),
    (2135, 'SUB-2135', 'SBM4', '¿CUÁL ES LA DIFERENCIA FUNDAMENTAL ENTRE ESTADO DE NECESIDAD JUSTIFICANTE Y EXCULPANTE CONFORME AL ARTÍCULO 20:', 'EL ESTADO DE NECESIDAD JUSTIFICANTE PRIORIZA EL BIEN PROTEGIDO, MIENTRAS EL EXCULPANTE LIBERA DE RESPONSABILIDAD POR VÍNCULO PERSONAL.', 'ART. 20', '184281'),
    (2136, 'SUB-2136', 'SBM4', 'EN EL USO LEGÍTIMO DE ARMAS POR LA POLICÍA NACIONAL DEL PERÚ, CONFORME AL ARTÍCULO 20, ¿CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA:', 'SE EXIME DE RESPONSABILIDAD PENAL SIEMPRE QUE EL USO DE ARMAS CAUSE LESIONES O MUERTE Y SE REALICE EN FORMA REGLAMENTARIA EN CUMPLIMIENTO DE LA FUNCIÓN CONSTITUCIONAL.', 'ART. 20', '184282'),
    (2137, 'SUB-2137', 'SBM4', '¿QUÉ REQUISITO SE EXIGE CUANDO SE ACTÚA POR ORDEN OBLIGATORIA DE AUTORIDAD COMPETENTE SEGÚN EL ARTÍCULO 20:', 'QUE LA ORDEN SEA EXPEDIDA EN EL EJERCICIO DE LAS FUNCIONES DE LA AUTORIDAD.', 'ART. 20', '184283'),
    (2138, 'SUB-2138', 'SBM4', 'RESPECTO A LA FUERZA FÍSICA IRRESISTIBLE COMO CAUSA EXIMENTE PENAL, INDIQUE EL SUPUESTO CORRECTO:', 'EXIME DE RESPONSABILIDAD SIEMPRE QUE LA FUERZA FÍSICA SEA IRRESISTIBLE Y PROVENGA DE UN TERCERO O DE LA NATURALEZA.', 'ART. 20', '184284'),
    (2139, 'SUB-2139', 'SBM4', '¿QUÉ CONDICIÓN INVALIDA LA LEGÍTIMA DEFENSA, SEGÚN EL ARTÍCULO 20:', 'LA EXISTENCIA DE UNA PROVOCACIÓN SUFICIENTE POR PARTE DE QUIEN SE DEFIENDE.', 'ART. 20', '184285'),
    (2140, 'SUB-2140', 'SBM4', '¿EN CUÁL DE LOS SIGUIENTES ESCENARIOS SE APLICA LA EXIMENTE DE RESPONSABILIDAD PENAL POR EL EJERCICIO LEGÍTIMO DE UN DERECHO, OFICIO O CARGO:', 'CUANDO EL AGENTE CUMPLE UN DEBER LEGAL EXIGIDO EN LA LEY.', 'ART. 20', '184286'),
    (2141, 'SUB-2141', 'SBM4', 'RESPECTO A LA DEFENSA DE BIENES JURÍDICOS PROPIOS MEDIANTE LA FUERZA LETAL, ¿EN CUÁL DE LOS ESCENARIOS SIGUIENTES NO SE CONFIGURA UNA EXIMENTE DE RESPONSABILIDAD PENAL:', 'CUANDO NO EXISTE PELIGRO ACTUAL PERO SE CREE QUE PODRÍA HABERLO EN EL FUTURO.', 'ART. 20', '184287'),
    (2142, 'SUB-2142', 'SBM4', 'DE ACUERDO CON EL ARTÍCULO 21 DEL CÓDIGO PENAL, EN LOS SUPUESTOS DE LOS CASOS REGULADOS POR EL ARTÍCULO 20, SI NO CONCURRE ALGUNO DE LOS REQUISITOS NECESARIOS PARA ELIMINAR COMPLETAMENTE LA RESPONSABILIDAD, QUÉ FACULTAD TIENE EL JUEZ RESPECTO A LA SANCIÓN QUE PODRÍA IMPONERSE:', 'EL JUEZ PUEDE REDUCIR PRUDENCIALMENTE LA PENA HASTA LÍMITES INFERIORES AL MÍNIMO LEGAL.', 'ART. 21', '184288'),
    (2143, 'SUB-2143', 'SBM4', 'SEGÚN EL SEGUNDO PÁRRAFO DEL ARTÍCULO 21 DEL CÓDIGO PENAL, ¿CUÁL ES EL PROCEDIMIENTO QUE DEBE SEGUIR LA AUTORIDAD RESPECTO AL ARMA DE FUEGO UTILIZADA POR QUIEN REPELE UNA AGRESIÓN ILEGÍTIMA, SIEMPRE QUE ESTÉ LEGALMENTE INSCRITA A SU NOMBRE:', 'SE INCAUTA EL ARMA DENTRO DE LAS 48 HORAS PARA FINES DE INVESTIGACIONES PRELIMINARES, BAJO RESPONSABILIDAD DE LA AUTORIDAD.', 'ART. 21', '184289'),
    (2144, 'SUB-2144', 'SBM4', 'SEGÚN EL ARTÍCULO 22 DEL CÓDIGO PENAL, ¿EN QUÉ SUPUESTO NO PROCEDERÁ LA REDUCCIÓN DE LA PENA SEÑALADA PARA EL HECHO PUNIBLE COMETIDO POR UN AGENTE ENTRE DIECISÉIS Y MENOS DE VEINTIÚN AÑOS:', 'CUANDO EL AGENTE INTEGRA UNA ORGANIZACIÓN CRIMINAL AL MOMENTO DEL HECHO.', 'ART. 22', '184290'),
    (2145, 'SUB-2145', 'SBM4', 'RESPECTO A LA SITUACIÓN PROCESAL DE UNA PERSONA MAYOR DE OCHENTA AÑOS CONDENADA POR UN DELITO, ¿CUÁL ES LA MEDIDA HUMANITARIA PREVISTA EN EL ARTÍCULO 22 DEL CÓDIGO PENAL:', 'PUEDE AFRONTAR SU CONDENA CONFORME A LO REGULADO EN LOS ARTÍCULOS 288 O 290 DEL NUEVO CÓDIGO PROCESAL PENAL.', 'ART. 22', '184291'),
    (2146, 'SUB-2146', 'SBM4', '¿EN CUÁL DE LOS SIGUIENTES SUPUESTOS NO ESTÁ EXCLUIDA LA POSIBILIDAD DE REDUCCIÓN PRUDENCIAL DE LA PENA POR EDAD, DE ACUERDO CON EL ARTÍCULO 22 DEL CÓDIGO PENAL:', 'COMISIÓN DE HOMICIDIO PRETERINTENCIONAL', 'ART. 22', '184292'),
    (2147, 'SUB-2147', 'SBM4', '¿QUÉ CRITERIO ESTABLECE EL ARTÍCULO 22 DEL CÓDIGO PENAL PARA QUE SE EXCLUYA LA RESPONSABILIDAD RESTRINGIDA POR LA EDAD EN CASO DE REITERACIÓN DELICTIVA:', 'CUANDO EL AGENTE HA INCURRIDO EN FORMA REITERADA EN LOS DELITOS PREVISTOS EN LOS ARTÍCULOS 111, TERCER PÁRRAFO, Y 124 CUARTO PÁRRAFO.', 'ART. 22', '184293'),
    (2148, 'SUB-2148', 'SBM4', '¿CUÁL DE LOS SIGUIENTES ELEMENTOS ES INDISPENSABLE PARA QUE SE CONFIGURE EL DELITO DE ORGANIZACIÓN CRIMINAL DE ACUERDO AL ARTÍCULO 317 DEL CÓDIGO PENAL PERUANO:', 'QUE EL GRUPO TENGA UNA COMPLEJA ESTRUCTURA DESARROLLADA Y MAYOR CAPACIDAD OPERATIVA, COMPUESTO POR TRES O MÁS PERSONAS, CON CARÁCTER PERMANENTE O POR TIEMPO INDEFINIDO.', 'ART. 317', '184294'),
    (2149, 'SUB-2149', 'SBM4', '¿EN QUÉ CIRCUNSTANCIA LA PENA POR ORGANIZACIÓN CRIMINAL SE INCREMENTA A NO MENOR DE QUINCE NI MAYOR DE VEINTE AÑOS DE PRIVACIÓN DE LIBERTAD, SEGÚN EL ARTÍCULO 317:', 'CUANDO EL AGENTE ACTÚA DESDE UN ESTABLECIMIENTO PENITENCIARIO O UTILIZANDO TECNOLOGÍAS DE LA INFORMACIÓN.', 'ART. 317', '184295'),
    (2150, 'SUB-2150', 'SBM4', 'SEGÚN LA DEFINICIÓN DE ORGANIZACIÓN CRIMINAL DEL ARTÍCULO 317, ¿QUÉ CARACTERÍSTICA NO ES INDISPENSABLE PARA CONFIGURAR DICHO DELITO:', 'LA EXISTENCIA DE UNA ESTRUCTURA JERÁRQUICA ESTRICTAMENTE MILITARIZADA.', 'ART. 317', '184296'),
    (2151, 'SUB-2151', 'SBM4', '¿CUÁL DE LOS SIGUIENTES NO CONSTITUYE UNA HIPÓTESIS AGRAVANTE CONFORME A LOS SUPUESTOS PREVISTOS EN EL SEGUNDO PÁRRAFO DEL ARTÍCULO 317 DEL CÓDIGO PENAL:', 'QUE LOS INTEGRANTES SEAN MENORES DE EDAD.', 'ART. 317', '184297'),
    (2152, 'SUB-2152', 'SBM4', 'RESPECTO A LA INHABILITACIÓN ESTABLECIDA EN EL ARTÍCULO 317, ¿A QUÉ ARTÍCULO REMITE Y CUÁLES SON ALGUNOS DE SUS NUMERALES APLICABLES:', 'REMITE AL ARTÍCULO 36, NUMERALES 1, 2, 4 Y 8 DEL CÓDIGO PENAL', 'ART. 317', '184298'),
    (2153, 'SUB-2153', 'SBM4', 'CONFORME AL ARTÍCULO 317, ¿QUÉ FINALIDAD DEBE PERSEGUIR UNA ORGANIZACIÓN CRIMINAL PARA SER CONSIDERADA COMO TAL BAJO EL TIPO PENAL:', 'OBTENER, DIRECTA O INDIRECTAMENTE, UN BENEFICIO ECONÓMICO U OTRO DE ORDEN MATERIAL.', 'ART. 317', '184299'),
    (2154, 'SUB-2154', 'SBM4', 'RESPECTO A LA TENTATIVA, CONFORME LO ESTABLECE EL ARTÍCULO 16 DEL CÓDIGO PENAL PERUANO, SEÑALE CUÁL DE LAS SIGUIENTES AFIRMACIONES ES CORRECTA:', 'EN LOS DELITOS DE TENTATIVA REGULADOS EN EL ARTÍCULO 108-B DEL CÓDIGO PENAL, LA PENA DISMINUIDA NO PUEDE SUPERAR UN TERCIO DEL MÍNIMO LEGAL.', 'ART. 16', '184300'),
    (2155, 'SUB-2155', 'SBM4', '¿CUÁL ES LA CONSECUENCIA JURÍDICA ESPECÍFICA ESTABLECIDA PARA LA TENTATIVA DE LOS DELITOS INCLUIDOS EN EL TÍTULO I-A Y EN EL CAPÍTULO IX DEL TÍTULO IV DEL LIBRO SEGUNDO DEL CÓDIGO PENAL PERUANO, SEGÚN EL ARTÍCULO 16:', 'LA DISMINUCIÓN DE LA PENA NO PUEDE SER MAYOR QUE UN TERCIO DEL MÍNIMO DE LA PENA LEGALMENTE FIJADA PARA DICHOS DELITOS.', 'ART. 16', '184301'),
    (2156, 'SUB-2156', 'SBM4', '¿CUÁL DE LAS SIGUIENTES CIRCUNSTANCIAS PUEDE SER CONSIDERADA COMO ATENUANTE SEGÚN EL ARTÍCULO 46 DEL CÓDIGO PENAL PERUANO, EN TANTO NO SEA ELEMENTO CONSTITUTIVO DEL DELITO NI ESTÉ PREVISTA ESPECÍFICAMENTE PARA SANCIONARLO:', 'EL OBRAR POR MÓVILES NOBLES O ALTRUISTAS', 'ART. 46', '184302'),
    (2157, 'SUB-2157', 'SBM4', 'SEÑALE LA ALTERNATIVA QUE CONSTITUYE UNA CIRCUNSTANCIA AGRAVANTE CONFORME AL ARTÍCULO 46 DEL CÓDIGO PENAL PERUANO RELACIONADO CON EL USO DE LA INTELIGENCIA ARTIFICIAL:', 'CUANDO PARA LA REALIZACIÓN DE LA CONDUCTA PUNIBLE SE UTILICE LA INTELIGENCIA ARTIFICIAL O TECNOLOGÍAS SIMILARES O ANÁLOGAS', 'ART. 46', '184303'),
    (2158, 'SUB-2158', 'SBM4', '¿EN QUÉ CASO, SEGÚN EL ARTÍCULO 46, SE CONSIDERA AGRAVANTE LA PLURALIDAD EN LA EJECUCIÓN DEL DELITO:', 'LA PLURALIDAD DE AGENTES QUE INTERVIENEN EN LA EJECUCIÓN DEL DELITO', 'ART. 46', '184304'),
    (2159, 'SUB-2159', 'SBM4', 'EL CÓDIGO PENAL, EN SU ARTÍCULO 46, DETERMINA UNA ATENUANTE SI EL IMPUTADO:', 'REPARA VOLUNTARIAMENTE EL DAÑO OCASIONADO O LAS CONSECUENCIAS DERIVADAS DEL PELIGRO GENERADO', 'ART. 46', '184305'),
    (2160, 'SUB-2160', 'SBM4', 'SELECCIONE UNA CIRCUNSTANCIA AGRAVANTE RELACIONADA CON LA CONDICIÓN DE LA VÍCTIMA SEGÚN EL ARTÍCULO 46:', 'QUE LA VÍCTIMA SEA MENOR DE EDAD O ADULTO MAYOR EN SITUACIÓN DE ESPECIAL VULNERABILIDAD', 'ART. 46', '184306'),
    (2161, 'SUB-2161', 'SBM4', '¿CUÁL DE LAS SIGUIENTES NO ES UNA ATENUANTE SEGÚN EL ARTÍCULO 46 DEL CÓDIGO PENAL PERUANO: Código Penal', 'REALIZAR LA CONDUCTA PUNIBLE ABUSANDO EL AGENTE DE SU PROFESIÓN', 'ART. 46', '184307'),
    (2162, 'SUB-2162', 'SBM4', '¿CUÁL SERÍA UNA AGRAVANTE SEGÚN EL ARTÍCULO 46 SI EL HECHO PUNIBLE SE COMETE DENTRO DE UN PENAL POR UN INTERNO:', 'SI SE COMETE POR QUIEN ESTÁ PRIVADO DE LIBERTAD DESDE EL INTERIOR DE UN LUGAR DE RECLUSIÓN', 'ART. 46', '184308'),
    (2163, 'SUB-2163', 'SBM4', 'DE LAS SIGUIENTES OPCIONES, SELECCIONE LA QUE CORRESPONDE A UNA AGRAVANTE CUANDO HAY MOTIVACIONES DISCRIMINATORIAS:', 'EJECUTAR EL DELITO BAJO MÓVILES DE INTOLERANCIA O DISCRIMINACIÓN POR RAZONES DE RAZA, IDENTIDAD ÉTNICA Y CULTURAL, ENTRE OTRAS', 'ART. 46', '184309'),
    (2164, 'SUB-2164', 'SBM4', 'CUANDO EL AGENTE INCREMENTA DELIBERADAMENTE LAS CONSECUENCIAS DAÑOSAS MÁS ALLÁ DE LO NECESARIO PARA CONSUMAR EL DELITO, SEGÚN EL ARTÍCULO 46 ESTO CONSTITUYE:', 'UNA AGRAVANTE GENÉRICA', 'ART. 46', '184310'),
    (2165, 'SUB-2165', 'SBM4', '¿CUÁL DE LAS SIGUIENTES ES UNA ATENUANTE SI LAS CIRCUNSTANCIAS PERSONALES O FAMILIARES INFLUYEN EN LA EJECUCIÓN DEL DELITO, DE ACUERDO AL ARTÍCULO 46:', 'LA INFLUENCIA DE APREMIANTES CIRCUNSTANCIAS PERSONALES O FAMILIARES EN LA EJECUCIÓN DE LA CONDUCTA PUNIBLE', 'ART. 46', '184311'),
    (2166, 'SUB-2166', 'SBM4', 'SELECCIONE LA ALTERNATIVA QUE CONSTITUYE UNA AGRAVANTE VINCULADA A LOS MEDIOS EMPLEADOS EN LA EJECUCIÓN DEL DELITO, SEGÚN EL ARTÍCULO 46 DEL CÓDIGO PENAL PERUANO:', 'EMPLEAR MEDIOS DE CUYO USO PUEDA RESULTAR PELIGRO COMÚN, COMO EXPLOSIVOS O VENENOS Código Penal', 'ART. 46', '184312'),
    (2167, 'SUB-2167', 'SBM4', 'IDENTIFIQUE CUÁL ES UNA AGRAVANTE GENERAL AL COMETER UN DELITO ABUSANDO EL AUTOR DE SU CARGO, PROFESIÓN O FUNCIÓN, DE ACUERDO AL ARTÍCULO 46:', 'EL AGENTE REALIZA LA CONDUCTA PUNIBLE ABUSANDO DE SU CARGO, FORMACIÓN, OFICIO O FUNCIÓN', 'ART. 46', '184313'),
    (2168, 'SUB-2168', 'SBM4', '¿CUÁL DE LAS SIGUIENTES CIRCUNSTANCIAS IMPLICA LA IMPOSICIÓN DE CADENA PERPETUA SEGÚN EL ARTÍCULO 129-Q DEL CÓDIGO PENAL PERUANO:', 'CUANDO EL AGENTE SE VALE DE SU POSICIÓN, CARGO O VÍNCULO FAMILIAR QUE LE OTORGA PARTICULAR AUTORIDAD SOBRE EL MENOR DE EDAD.', 'ART. 129-Q', '184314'),
    (2169, 'SUB-2169', 'SBM4', '¿EN CUÁL DE LOS SIGUIENTES SUPUESTOS SE APLICA LA PENA PRIVATIVA DE LIBERTAD NO MENOR DE DOCE NI MAYOR DE VEINTICINCO AÑOS SEGÚN EL ARTÍCULO 129-Q:', 'CUANDO EL DELITO COMETIDO O INTENTADO TIENE COMO OBJETIVO ACTOS DE SICARIATO, ROBO AGRAVADO, TRÁFICO ILÍCITO DE DROGAS O INTEGRA A UNA ORGANIZACIÓN CRIMINAL.', 'ART. 129-Q', '184315'),
    (2170, 'SUB-2170', 'SBM4', 'SEGÚN EL ARTÍCULO 129-Q, ¿CUÁL DE LOS SIGUIENTES ELEMENTOS NO ES NECESARIO PARA LA CONFIGURACIÓN DEL TIPO PENAL DE CAPTACIÓN DE MENORES PARA LA COMISIÓN DE DELITOS:', 'LA PARTICIPACIÓN ACTIVA DEL MENOR EN LA EJECUCIÓN DEL DELITO REQUERIDO', 'ART. 129-Q', '184316'),
    (2171, 'SUB-2171', 'SBM4', 'EL ARTÍCULO 129-Q DEL CÓDIGO PENAL SEÑALA QUE LA PENA AUMENTARÁ SI EL DELITO COMETIDO O INTENTADO POR EL MENOR ES:', 'ROBO AGRAVADO, SICARIATO, TRÁFICO ILÍCITO DE DROGAS O INTEGRAR A UNA ORGANIZACIÓN CRIMINAL.', 'ART. 129-Q', '184317'),
    (2172, 'SUB-2172', 'SBM4', 'RESPECTO AL ARTÍCULO 129-Q, ¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS DESCRIBE CORRECTAMENTE UN SUPUESTO DE CAPTACIÓN EN SITUACIÓN DE VULNERABILIDAD: Código Penal', 'PERSUADIR A UN MENOR CUYA SITUACIÓN FAMILIAR LO COLOCA EN DESVENTAJA SOCIAL NOTABLE PARA QUE PARTICIPE EN LA COMISIÓN DE DELITOS.', 'ART. 129-Q', '184318'),
    (2173, 'SUB-2173', 'SBM4', '¿QUÉ ELEMENTO SUBJETIVO SE REQUIERE PARA IMPUTAR LA RESPONSABILIDAD PENAL EN BASE AL ARTÍCULO 129-Q:', 'DOLO DIRECTO EN LA CAPTACIÓN Y PERSUASIÓN DEL MENOR PARA DELITOS.', 'ART. 129-Q', '184319'),
    (2174, 'SUB-2174', 'SBM4', '¿CUÁL DE LAS SIGUIENTES CONDUCTAS AGRAVARÍA LA PENA POR EL DELITO DE EXHIBICIONES Y PUBLICACIONES OBSCENAS SEGÚN EL ARTÍCULO 183 DEL CÓDIGO PENAL PERUANO:', 'MOSTRAR IMÁGENES OBSCENAS A UN MENOR DE DIECIOCHO AÑOS.', 'ART. 183', '184320'),
    (2175, 'SUB-2175', 'SBM4', 'PARA QUE SE CONFIGURE LA AGRAVANTE DE QUIEN INCITA A UN MENOR DE 18 AÑOS A LA PRÁCTICA DE UN ACTO SEXUAL, ¿CUÁL ES EL ELEMENTO ESENCIAL QUE DEBE CUMPLIRSE:', 'QUE LA INCITACIÓN SEA DESTINADA A FACILITAR LA ENTRADA A LUGARES CON PROPÓSITOS SEXUALES', 'ART. 183', '184321'),
    (2176, 'SUB-2176', 'SBM4', '¿QUÉ SUCEDE SI UNA PERSONA, SIN SER DOCENTE NI FUNCIONARIO PÚBLICO, COMETE UNA CONDUCTA OBSCENA EN UN ESPECTÁCULO PERMITIDO Y UN MENOR DE EDAD INGRESA POR ERROR:', 'SE CONFIGURA AGRAVANTE SI LA CONDUCTA OCURRIÓ EN PRESENCIA DEL MENOR DE EDAD.', 'ART. 183', '184322'),
    (2177, 'SUB-2177', 'SBM4', 'SEGÚN EL ARTÍCULO 183, ¿CUÁL DE LAS SIGUIENTES ALTERNATIVAS AMPLÍA LA CONDICIÓN DEL SUJETO ACTIVO EN EL AGRAVANTE DEL TIPO PENAL:', 'QUIEN TENGA POSICIÓN DE GARANTE Y DEBER DE CUSTODIA SOBRE UN MENOR O PERSONA VULNERABLE. Código Penal', 'ART. 183', '184323'),
    (2178, 'SUB-2178', 'SBM4', 'EN EL CASO DE UN DOCENTE QUE PERMITE A UN MENOR DE EDAD EL INGRESO A UN CINE DONDE SE EXHIBEN ACTOS DE ÍNDOLE SEXUAL, QUÉ AGRAVANTE APLICARÍAS:', 'AGRAVANTE POR SER DOCENTE O PERSONAL ADMINISTRATIVO DE UNA INSTITUCIÓN EDUCATIVA.', 'ART. 183', '184324'),
    (2179, 'SUB-2179', 'SBM4', '¿CUÁL DE LOS SIGUIENTES SUPUESTOS NO CONSTITUYE UNA AGRAVANTE SEGÚN EL ARTÍCULO 183 DEL CÓDIGO PENAL PERUANO:', 'LA CONDUCTA OBSCENA ES REALIZADA FRENTE A PERSONAS ADULTAS QUE CONSIENTEN EL ACTO.', 'ART. 183', '184325'),
    (2180, 'SUB-2180', 'SBM4', '¿QUÉ DIFERENCIA SUSTANTIVA PRESENTA EL SEGUNDO SUPUESTO AGRAVADO RESPECTO DEL PRIMERO EN EL ARTÍCULO 183 DEL CÓDIGO PENAL PERUANO:', 'LA NATURALEZA DE LA CONDUCTA RECAE EN LA ENTREGA DE OBJETOS, MIENTRAS EL OTRO EN LA INCITACIÓN A LA PRÁCTICA DE ACTOS', 'ART. 183', '184326'),
    (2181, 'SUB-2181', 'SBM4', '¿QUÉ, MARCO LEGAL REGULA EL USO DE LA FUERZA POR PARTE DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD CONSTITUCIONAL?', 'DECRETO LEGISLATIVO 1186.', 'ART. 1', '184701'),
    (2182, 'SUB-2182', 'SBM4', '¿CUÁL ES EL OBJETO DEL DECRETO LEGISLATIVO 1186?:', 'REGULAR EL USO DE LA FUERZA POR PARTE DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 1', '184702'),
    (2183, 'SUB-2183', 'SBM4', 'CUÁL ES EL ALCANCE DEL DECRETO LEGISLATIVO 1186:', 'A TODO EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD QUE USA LA FUERZA EN DEFENSA DE LA PERSONA, LA SOCIEDAD Y EL ESTADO.', 'ART. 2', '184703'),
    (2184, 'SUB-2184', 'SBM4', 'ALCANZAN A TODO EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD QUE USA LA FUERZA EN DEFENSA DE LA PERSONA, LA SOCIEDAD Y EL ESTADO; ESTE DECRETO LEGISLATIVO REGULA:', 'EL USO DE LA FUERZA POR PARTE DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 2', '184704'),
    (2185, 'SUB-2185', 'SBM4', 'ES EL MEDIO QUE EN SUS DIFERENTE NIVELES USA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, DENTRO DEL MARCO DE LA LEY, PARA LOGRAR EL CONTROL DE UNA SITUACIÓN QUE CONSTITUYE UNA AMENAZA O ATENTA CONTRA LA SEGURIDAD, EL ORDEN PÚBLICO, LA INTEGRIDAD O LA VIDA DE LAS PERSONAS:', 'FUERZA.', 'ART. 3 LIT. A', '184705'),
    (2186, 'SUB-2186', 'SBM4', 'ES LA GRADUACIÓN Y ADECUACIÓN, POR PARTE DEL PERSONAL POLICIAL, DE LOS MEDIOS Y MÉTODOS A EMPLEAR TENIENDO EN CUENTA EL NIVEL DE COOPERACIÓN, RESISTENCIA O AGRESIÓN QUE REPRESENTE LA PERSONA A INTERVENIR O LA SITUACIÓN A CONTROLAR; CORRESPONDE A LA DEFINICIÓN DE:', 'USO PROGRESIVO Y DIFERENCIADO DE LA FUERZA.', 'ART. 3 LIT. B', '184706'),
    (2187, 'SUB-2187', 'SBM4', 'SON LAS ARMAS, EQUIPO, ACCESORIOS Y OTROS ELEMENTOS DE APOYO, AUTORIZADOS O PROPORCIONADOS POR EL ESTADO, QUE EMPLEA EL PERSONAL POLICIAL PARA ENFRENTAR UNA AMENAZA O ATENTADO CONTRA LA SEGURIDAD, EL ORDEN PÚBLICO, LA INTEGRIDAD O LA VIDA DE LAS PERSONAS; CORRESPONDE A LA DEFINICIÓN DE:', 'MEDIOS DE POLICÍA.', 'ART. 3 LIT. C', '184707'),
    (2188, 'SUB-2188', 'SBM4', 'ES LA OBLIGACIÓN DEL PERSONAL POLICIAL EN EL EJERCICIO DE LA AUTORIDAD QUE REPRESENTA, DE GARANTIZAR EL ORDEN Y LA SEGURIDAD SIRVIENDO A LA COMUNIDAD Y PROTEGIENDO A LAS PERSONAS EN EL MARCO DE SUS COMPETENCIAS, FUNCIONES Y ATRIBUCIONES LEGALMENTE ESTABLECIDAS. CORRESPONDE A LA:', 'DEFINICIÓN DE CUMPLIMIENTO DEL DEBER.', 'ART. 3 LIT. D', '184708'),
    (2189, 'SUB-2189', 'SBM4', 'EL USO DE LA FUERZA DEBE ORIENTARSE AL LOGRO DE UN OBJETIVO LEGAL. LOS MEDIOS Y MÉTODOS UTILIZADOS EN CUMPLIMIENTO DEL DEBER DEBEN ESTAR AMPARADOS EN EL MARCO DEL DERECHO INTERNACIONAL DE LOS DERECHOS HUMANOS, LA CONSTITUCIÓN POLÍTICA DEL PERÚ, Y DEMÁS NORMAS NACIONALES SOBRE LA MATERIA; CORRESPONDE AL PRINCIPIO DE:', 'LEGALIDAD.', 'ART. 4 LIT. A', '184709'),
    (2190, 'SUB-2190', 'SBM4', 'EL USO DE LA FUERZA EN EL CUMPLIMIENTO DEL DEBER ES NECESARIO, CUANDO OTROS MEDIOS RESULTEN INEFICACES O NO GARANTICEN DE NINGUNA MANERA EL LOGRO DEL OBJETIVO LEGAL BUSCADO. CORRESPONDE AL PRINCIPIO DE:', 'NECESIDAD.', 'ART. 4 LIT. B', '184710'),
    (2191, 'SUB-2191', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN EL PLANEAMIENTO, CONDUCCIÓN Y EJECUCIÓN DE OPERACIONES EN EL EJERCICIO DE SUS FUNCIONES, OBSERVARÁ Y SE SUJETARÁ A:', 'PRINCIPIOS CONTEMPLADOS EN EL PRESENTE DECRETO LEGISLATIVO', 'ART. 4 LIT. C', '184711'),
    (2192, 'SUB-2192', 'SBM4', 'EL USO DE LA FUERZA DEBE ORIENTARSE AL LOGRO DE UN:', 'OBJETIVO LEGAL.', 'ART. 4 LIT. A', '184712'),
    (2193, 'SUB-2193', 'SBM4', 'EN EL PRINCIPIO DE NECESIDAD; PARA DETERMINAR EL NIVEL DE FUERZA A USAR, SE DEBE CONSIDERAR, RAZONABLEMENTE, ENTRE OTRAS CIRCUNSTANCIAS EL NIVEL DE:', 'COOPERACIÓN.', 'ART. 4, 4.1, LIT. B', '184713'),
    (2194, 'SUB-2194', 'SBM4', '¿QUÉ DEBE USARSE DE MANERA PROGRESIVA Y DIFERENCIADA, DE CONFORMIDAD CON LOS PRINCIPIOS Y LOS NIVELES ESTABLECIDOS?:', 'LA FUERZA.', 'ART. 6', '184714'),
    (2195, 'SUB-2195', 'SBM4', 'DENTRO DE LOS NIVELES DEL USO DE LA FUERZA, EXISTEN DOS RESISTENCIAS EN LOS NIVELES DE COOPERACIÓN, RESISTENCIA O AGRESIVIDAD DEL CIUDADANO A INTERVENIR. MARQUE LO CORRECTO:', 'RESISTENCIA PASIVA Y RESISTENCIA ACTIVA.', 'ART. 7, 7.1 LIT. A y B', '184715'),
    (2196, 'SUB-2196', 'SBM4', '¿CUÁLES SON LAS CLASES DE RESISTENCIA PASIVA?:', 'RIESGO LATENTE, COOPERADOR Y NO COOPERADOR.', 'ART. 7, 7.1 LIT. A', '184716'),
    (2197, 'SUB-2197', 'SBM4', '¿CUÁLES SON LAS CLASES DE RESISTENCIA ACTIVA?', 'RESISTENCIA FÍSICA, AGRESIÓN NO LETAL Y AGRESIÓN LETAL.', 'ART. 7, 7.1 LIT. B', '184717'),
    (2198, 'SUB-2198', 'SBM4', 'NO ACATA LAS INDICACIONES. NO REACCIONA NI AGREDE, CORRESPONDE A LA DEFINICIÓN DE:', 'NO COOPERADOR.', 'ART. 7.1 LIT. A, NUM. 3', '184718'),
    (2199, 'SUB-2199', 'SBM4', 'ES LA AMENAZA PERMANENTE NO VISIBLE PRESENTE EN TODA INTERVENCIÓN POLICIAL, CORRESPONDE A LA DEFINICIÓN DE:', 'RIESGO LATENTE.', 'ART. 7.1 LIT. A, NUM. 1', '184719'),
    (2200, 'SUB-2200', 'SBM4', 'SE OPONE A SU REDUCCIÓN, INMOVILIZACIÓN Y/O CONDUCCIÓN, LLEGANDO A UN NIVEL DE DESAFÍO FÍSICO, CORRESPONDE A LA DEFINICIÓN DE:', 'RESISTENCIA FÍSICA.', 'ART. 7.1 LIT. B, NUM. 1', '184720')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

