INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2201 a 2300
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2201, 'SUB-2201', 'SBM4', 'AGRESIÓN FÍSICA AL PERSONAL POLICIAL O PERSONAS INVOLUCRADAS EN LA INTERVENCIÓN, PUDIENDO UTILIZAR OBJETOS QUE ATENTEN CONTRA LA INTEGRIDAD FÍSICA, CORRESPONDE A LA DEFINICIÓN DE:', 'AGRESIÓN NO LETAL.', 'ART. 7.1 LIT. B, NUM. 2', '184721'),
    (2202, 'SUB-2202', 'SBM4', '¿CUÁL ES LA DEFINICIÓN DE AGRESIÓN LETAL?:', 'ACCIÓN QUE PONE EN PELIGRO INMINENTE DE MUERTE O LESIONES GRAVES AL EFECTIVO POLICIAL O A PERSONAS INVOLUCRADAS EN LA INTERVENCIÓN.', 'ART. 7.1 LIT. B, NUM. 3', '184722'),
    (2203, 'SUB-2203', 'SBM4', 'LA ACCIÓN QUE PONE EN PELIGRO INMINENTE DE MUERTE O LESIONES GRAVES AL EFECTIVO POLICIAL O A PERSONAS INVOLUCRADAS EN LA INTERVENCIÓN. CORRESPONDE A LA DEFINICIÓN DE: Decreto Legislativo N°1186 - Ley que Regula el Uso de la Fuerza por Parte de la PNP y su Reglamento', 'AGRESIÓN LETAL.', 'ART. 7, 7.1 LIT. B, NUM. 3', '184723'),
    (2204, 'SUB-2204', 'SBM4', 'DENTRO DE LOS NIVELES DEL USO DE LA FUERZA, EXISTEN DOS NIVELES DE USO DE LA FUERZA POR EL PERSONAL DE LA POLICÍA NACIONAL. MARQUE LO CORRECTO:', 'NIVELES PREVENTIVOS Y NIVELES REACTIVOS.', 'ART. 7, 7.2 LIT. A y B', '184724'),
    (2205, 'SUB-2205', 'SBM4', 'INDIQUE CUÁL DE LOS ENUNCIADOS CORRESPONDEN A LOS NIVELES PREVENTIVOS:', 'PRESENCIA POLICIAL, VERBALIZACIÓN Y CONTROL DE CONTACTO.', 'ART. 7, 7.2 LIT. A', '184725'),
    (2206, 'SUB-2206', 'SBM4', 'INDIQUE CUÁL DE LOS ENUNCIADOS CORRESPONDEN A LOS NIVELES REACTIVOS:', 'CONTROL FÍSICO, TÁCTICAS DEFENSIVAS NO LETALES Y FUERZA LETAL.', 'ART. 7, 7.2 LIT. B', '184726'),
    (2207, 'SUB-2207', 'SBM4', 'ENTENDIDA COMO DEMOSTRACIÓN DE AUTORIDAD DEL PERSONAL DE LA POLICÍA NACIONAL UNIFORMADO, EQUIPADO, EN ACTITUD DE ALERTA Y REALIZANDO UN CONTROL VISUAL, QUE PREVIENE Y DISUADE LA COMISIÓN DE UNA INFRACCIÓN O UN DELITO, CORRESPONDE A LA DEFINICIÓN DE?:', 'PRESENCIA POLICIAL.', 'ART. 7.2 LIT. A, NUM. 1', '184727'),
    (2208, 'SUB-2208', 'SBM4', 'INDIQUE LA DEFINICIÓN CORRECTA DE CONTROL DE CONTACTO:', 'ES EL USO DE TÉCNICAS DE COMUNICACIÓN, NEGOCIACIÓN Y PROCEDIMIENTOS DESTINADOS A GUIAR, CONTENER LA ACCIÓN O ACTITUD DE LA PERSONA O GRUPOS A SER INTERVENIDOS.', 'ART. 7, 7.2 LIT. A, NUM. 3', '184728'),
    (2209, 'SUB-2209', 'SBM4', '¿CUÁL ES LA DEFINICIÓN CORRECTA DE CONTROL FÍSICO, QUE SE ENCUENTRA DENTRO DE LOS NIVELES DEL USO DE LA FUERZA?.', 'ES EL USO DE LAS TÉCNICAS POLICIALES QUE PERMITEN CONTROLAR, REDUCIR, INMOVILIZAR Y CONDUCIR A LA PERSONA INTERVENIDA, EVITANDO EN LO POSIBLE CAUSAR LESIONES.', 'ART. 7.2 LIT. B, NUM. 1', '184729'),
    (2210, 'SUB-2210', 'SBM4', 'CUAL ES LA DEFINICIÓN CORRECTA, DE TÁCTICAS DEFENSIVAS NO LETALES, QUE SE ENCUENTRA DENTRO DE LOS NIVELES DEL USO DE LA FUERZA:', 'ES EL USO DE MEDIOS DE POLICÍA NO LETALES PARA CONTRARRESTAR Y/O SUPERAR EL NIVEL DE AGRESIÓN O RESISTENCIA.', 'ART. 7.2 LIT. B, NUM. 2', '184730'),
    (2211, 'SUB-2211', 'SBM4', 'ES EL USO DE LAS TÉCNICAS POLICIALES QUE PERMITEN CONTROLAR, REDUCIR, INMOVILIZAR Y CONDUCIR A LA PERSONA INTERVENIDA, EVITANDO EN LO POSIBLE CAUSAR LESIONES. CORRESPONDE A LA DEFINICIÓN DE:', 'CONTROL FÍSICO.', 'ART. 7, 7.2 LIT. B, NUM. 1', '184731'),
    (2212, 'SUB-2212', 'SBM4', 'ES EL USO DE MEDIOS DE POLICÍA NO LETALES PARA CONTRARRESTAR Y/O SUPERAR EL NIVEL DE AGRESIÓN O RESISTENCIA. CORRESPONDE A LA DEFINICIÓN DE:', 'TÁCTICAS DEFENSIVAS NO LETALES.', 'ART. 7, 7.2 LIT. A, NUM. 2', '184732'),
    (2213, 'SUB-2213', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, OBSERVANDO LO PRESCRITO EN LOS ARTÍCULOS 4, 6 Y EL NUMERAL 7.2, SE IDENTIFICA COMO TAL, INDIVIDUALIZA A LA PERSONA O PERSONAS A INTERVENIR Y DA UNA CLARA ADVERTENCIA DE SU INTENCIÓN DE USAR LA FUERZA, CON TIEMPO SUFICIENTE PARA QUE SE TOME EN CUENTA, SALVO QUE ESA ADVERTENCIA LO PONGA EN PELIGRO O CREARA UN GRAVE RIESGO DE MUERTE O DE LESIONES GRAVES A OTRAS PERSONAS, O CUANDO LA ADVERTENCIA RESULTARA EVIDENTEMENTE INADECUADA DADAS LAS CIRCUNSTANCIAS DEL CASO. CORRESPONDE A LA DEFINICIÓN DE:.', 'CIRCUNSTANCIAS Y REGLAS DE CONDUCTA EN EL USO DE LA FUERZA.', 'ART. 8, 8.1', '184733'),
    (2214, 'SUB-2214', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PUEDE USAR LA FUERZA, DE CONFORMIDAD CON LOS ARTÍCULOS 4, 6 Y EL NUMERAL 7.2, EN LAS SIGUIENTES CIRCUNSTANCIAS:', 'DETENER EN FLAGRANTE DELITO O POR MANDATO JUDICIAL CONFORME A LEY.', 'ART. 8, 8.2, LIT. A', '184734'),
    (2215, 'SUB-2215', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PUEDE USAR LA FUERZA, DE CONFORMIDAD CON LOS ARTÍCULOS 4, 6 Y EL NUMERAL 7.2, EN LAS SIGUIENTES CIRCUNSTANCIAS:', 'CUMPLIR UN DEBER U ÓRDENES LÍCITAS DICTADAS POR LAS AUTORIDADES COMPETENTES.', 'ART. 8.2, LIT. B', '184735'),
    (2216, 'SUB-2216', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PUEDE USAR LA FUERZA, DE CONFORMIDAD CON LOS ARTÍCULOS 4, 6 Y EL NUMERAL 7.2, EN LAS SIGUIENTES CIRCUNSTANCIAS:', 'PREVENIR LA COMISIÓN DE DELITOS Y FALTAS.', 'ART. 8.2, LIT. C', '184736'),
    (2217, 'SUB-2217', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PUEDE USAR LA FUERZA, DE CONFORMIDAD CON LOS ARTÍCULOS 4, 6 Y EL NUMERAL 7.2, EN LAS SIGUIENTES CIRCUNSTANCIAS:', 'PROTEGER O DEFENDER BIENES JURÍDICOS TUTELADOS.', 'ART. 8.2, LIT. D', '184737'),
    (2218, 'SUB-2218', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PUEDE USAR LA FUERZA, DE CONFORMIDAD CON LOS ARTÍCULOS 4, 6 Y EL NUMERAL 7.2, EN LAS SIGUIENTES CIRCUNSTANCIAS:', 'CONTROLAR A QUIEN OPONGA RESISTENCIA A LA AUTORIDAD.', 'ART. 8.2, LIT. E', '184738'),
    (2219, 'SUB-2219', 'SBM4', '¿EN QUÉ SITUACIÓN, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ HACER USO DEL ARMA DE FUEGO?', 'EN DEFENSA PROPIA O DE OTRAS PERSONAS EN CASO DE PELIGRO REAL E INMINENTE DE MUERTE O LESIONES GRAVES.', 'ART. 8, 8.3, LIT. A', '184739'),
    (2220, 'SUB-2220', 'SBM4', 'EN QUE SITUACIÓN, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ HACER USO DEL ARMA DE FUEGO:', 'CUANDO SE PRODUZCA UNA SITUACIÓN QUE IMPLIQUE UNA SERIA AMENAZA PARA LA VIDA DURANTE LA COMISIÓN DE UN DELITO PARTICULARMENTE GRAVE.', 'ART. 8, 8.3, LIT. B', '184740'),
    (2221, 'SUB-2221', 'SBM4', '¿EN QUE SITUACIÓN, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ HACER USO DEL ARMA DE FUEGO:', 'CUANDO SE GENERE UN PELIGRO REAL E INMINENTE DE MUERTE O LESIONES GRAVES COMO CONSECUENCIA DE LA RESISTENCIA OFRECIDA POR LA PERSONA QUE VAYA A SER DETENIDA.', 'ART. 8, 8.3, LIT. C', '184741'),
    (2222, 'SUB-2222', 'SBM4', '¿EN QUÉ SITUACIÓN, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ HACER USO DEL ARMA DE FUEGO:', 'CUANDO LA VIDA DE UNA PERSONA ES PUESTA EN RIESGO REAL, INMINENTE Y ACTUAL POR QUIEN SE ESTA FUGANDO.', 'ART. 8, 8.3, LIT. D', '184742'),
    (2223, 'SUB-2223', 'SBM4', '¿EN QUE SITUACIÓN, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ HACER USO DEL ARMA DE FUEGO:', 'CUANDO SE GENERE UN PELIGRO REAL O INMINENTE DE MUERTE DEL PERSONAL POLICIAL U OTRA PERSONA, POR LA ACCIÓN DE QUIEN PARTICIPA DE UNA REUNIÓN TUMULTUARIA VIOLENTA.', 'ART. 8, 8.3, LIT. E', '184743'),
    (2224, 'SUB-2224', 'SBM4', 'ACCIONES POSTERIORES AL USO DE LA FUERZA.- CON POSTERIORIDAD AL USO DE LA FUERZA EL PERSONAL DE LA POLICÍA NACIONAL DEBERÁ REALIZAR LAS SIGUIENTES ACCIONES. SEÑALE LO CORRECTO:', 'ADOPTAR LAS MEDIDAS NECESARIAS PARA QUE SE BRINDE ASISTENCIA Y SERVICIOS MÉDICOS A LAS PERSONAS HERIDAS O AFECTADAS, SALVO QUE EXISTAN CIRCUNSTANCIAS QUE IMPIDAN SU REALIZACIÓN.', 'ART. 9, LIT. A', '184744'),
    (2225, 'SUB-2225', 'SBM4', 'CON POSTERIORIDAD AL USO DE LA FUERZA EL PERSONAL DE LA POLICÍA NACIONAL DEBERÁ ADOPTAR LAS MEDIDAS NECESARIAS PARA COMUNICAR LO SUCEDIDO A LOS FAMILIARES DE LAS PERSONAS FALLECIDAS, HERIDAS O AFECTADAS O A AQUELLAS QUE ESTAS ÚLTIMAS INDIQUEN, SALVO QUE. SEÑALE LO CORRECTO:', 'EXISTAN CIRCUNSTANCIAS QUE IMPIDAN SU REALIZACIÓN.', 'ART. 9, LIT. B', '184745'),
    (2226, 'SUB-2226', 'SBM4', 'CON POSTERIORIDAD AL USO DE LA FUERZA EL PERSONAL DE LA POLICÍA NACIONAL DEBERÁ PRESENTAR UN INFORME A LA UNIDAD POLICIAL CORRESPONDIENTE INDICANDO LAS CIRCUNSTANCIAS, LOS MEDIOS EMPLEADOS, EL PERSONAL INTERVINIENTE, EL TIPO DE ARMAS Y LAS MUNICIONES UTILIZADAS, EL NÚMERO DE IDENTIDAD DE LOS AFECTADOS, Y: SEÑALE LO CORRECTO:', 'LAS ASISTENCIAS Y EVACUACIONES REALIZADAS.', 'ART. 9, LIT. C', '184746'),
    (2227, 'SUB-2227', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A: Decreto Legislativo N°1186 - Ley que Regula el Uso de la Fuerza por Parte de la PNP y su Reglamento', 'LA PROTECCIÓN Y RESPETO DE SU VIDA, INTEGRIDAD PERSONAL, DIGNIDAD Y A LAS CONSIDERACIONES QUE SU AUTORIDAD LE OTORGA.', 'ART. 10 LIT. A', '184747'),
    (2228, 'SUB-2228', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A:', 'NO ACATAR DISPOSICIONES U ÓRDENES SUPERIORES PARA EL USO DE LA FUERZA CUANDO ESTAS SEAN MANIFIESTAMENTE ILÍCITAS O ARBITRARIAS.', 'ART. 10 LIT. B', '184748'),
    (2229, 'SUB-2229', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A:', 'RECIBIR FORMACIÓN, CAPACITACIÓN Y ENTRENAMIENTO PERMANENTE SOBRE EL USO DE LA FUERZA EN TODOS LOS NIVELES EDUCATIVOS, EN MATERIA DE DERECHOS HUMANOS.', 'ART. 10 LIT. C', '184749'),
    (2230, 'SUB-2230', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A:', 'LA ASIGNACIÓN DE ARMAMENTO, VESTUARIO Y EQUIPO QUE GARANTICEN EL USO ADECUADO DE LA FUERZA.', 'ART. 10 LIT. D', '184750'),
    (2231, 'SUB-2231', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A:', 'RECIBIR TRATAMIENTO Y ASISTENCIA MÉDICA, POR CUENTA DEL ESTADO CUANDO RESULTE AFECTADO EN CUMPLIMIENTO DE SU DEBER.', 'ART. 10 LIT. E', '184751'),
    (2232, 'SUB-2232', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A:', 'RECIBIR ORIENTACIÓN PSICOLÓGICA POR CUENTA DEL ESTADO PARA SOBRELLEVAR LAS TENSIONES GENERADAS POR EL USO DE LA FUERZA.', 'ART. 10 LIT. F', '184752'),
    (2233, 'SUB-2233', 'SBM4', 'EN EL EJERCICIO DE SU FUNCIÓN RELACIONADA AL USO DE LA FUERZA, EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE DERECHO A:', 'RECIBIR ASESORAMIENTO Y DEFENSA LEGAL POR CUENTA DEL ESTADO, CUANDO SE HAYA USADO LA FUERZA EN EL CONTEXTO DEL DECRETO LEGISLATIVO 1186.', 'ART. 10 LIT. G', '184753'),
    (2234, 'SUB-2234', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ TIENE LA RESPONSABILIDAD DE INFORMAR TODA OCURRENCIA RELACIONADA AL USO DE LA FUERZA O DE ARMA DE FUEGO, AL:', 'COMANDO POLICIAL.', 'ART. 11, 11.1', '184754'),
    (2235, 'SUB-2235', 'SBM4', 'DENTRO DE LAS RESPONSABILIDADES, CUANDO AL USAR LA FUERZA SE OCASIONARA LESIONES O MUERTE, SE DISPONE:', 'LA INVESTIGACIÓN ADMINISTRATIVA CORRESPONDIENTE Y SE DA INMEDIATA CUENTA DE LOS HECHOS A LAS AUTORIDADES COMPETENTES.', 'ART. 11, 11.2', '184755'),
    (2236, 'SUB-2236', 'SBM4', 'RESPONSABILIDADES: CUANDO SE USEN LAS ARMAS DE FUEGO, EL PERSONAL DE LA POLICÍA NACIONAL NO PUEDE:', 'ALEGAR OBEDIENCIA A ÓRDENES SUPERIORES SI TENIA CONOCIMIENTO QUE EL USO DE ESTA ERA MANIFIESTAMENTE ILÍCITA.', 'ART. 11, 11.3', '184756'),
    (2237, 'SUB-2237', 'SBM4', 'LOS SUPERIORES JERÁRQUICOS INCURREN EN RESPONSABILIDAD, CUANDO CONOCIENDO O DEBIENDO CONOCER, EL USO ILÍCITO DE LA FUERZA POR EL PERSONAL POLICIAL A SUS ORDENES; INDIQUE LA CORRECTA:', 'NO ADOPTEN LAS MEDIDAS NECESARIAS PARA IMPEDIR O NEUTRALIZAR DICHO USO O NO DENUNCIARON EL HECHO OPORTUNAMENTE.', 'ART. 11, 11.4', '184757'),
    (2238, 'SUB-2238', 'SBM4', 'SEÑALE UNA DE LAS RESPONSABILIDADES DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ:', 'EL USO DE LA FUERZA QUE CONTRAVENGA EL PRESENTE DECRETO LEGISLATIVO GENERA RESPONSABILIDAD ADMINISTRATIVA DISCIPLINARIA, PENAL Y CIVIL.', 'ART. 11, 11.5', '184758'),
    (2239, 'SUB-2239', 'SBM4', 'ADOPTARÁ LAS MEDIDAS INSTITUCIONALES PARA, EVALUAR LA SITUACIÓN ACTUAL DEL ARMAMENTO, MUNICIÓN, EQUIPOS Y OTROS ACCESORIOS NECESARIOS PARA EL USO DE LA FUERZA POR PARTE DE LA POLICÍA NACIONAL DEL PERÚ:', 'EL MINISTERIO DEL INTERIOR.', 'DISP. COMP. FIN, SEGUNDA DISPOSICIÓN, LIT. A', '184759'),
    (2240, 'SUB-2240', 'SBM4', 'A QUIÉN CORRESPONDE ADOPTAR LAS MEDIDAS INSTITUCIONALES PARA ACTUALIZAR EL PROGRAMA DE ADQUISICIÓN DE ARMAMENTO LETAL Y NO LETAL, MUNICIONES, EQUIPAMIENTO ANTI MOTÍN, VEHÍCULOS ANTI MOTÍN Y OTROS ACCESORIOS PARA LA POLICÍA NACIONAL DEL PERÚ:', 'AL MINISTERIO DEL INTERIOR.', 'DISP. COMP. FIN, SEGUNDA DISPOSICIÓN, LIT. B', '184760'),
    (2241, 'SUB-2241', 'SBM4', 'DENTRO DE LAS DISPOSICIONES COMPLEMENTARIAS FINALES DEL DECRETO LEGISLATIVO, EL MINISTERIO DEL INTERIOR ADOPTARÁ LAS MEDIDAS INSTITUCIONALES PARA:', 'ADECUAR LOS PLANES DE CAPACITACIÓN Y ENTRENAMIENTO PARA EL PERSONAL POLICIAL EN APLICACIÓN DE LA PRESENTE NORMA.', 'DISP. COMP. FIN, SEGUNDA DISPOSICIÓN, LIT. C', '184761'),
    (2242, 'SUB-2242', 'SBM4', '¿QUÉ ENTIDAD SUPERVISA LA ADECUACIÓN Y CONFORMIDAD DE LOS CONTENIDOS DE LAS ACTIVIDADES EDUCATIVAS RELACIONADAS AL USO DE LA FUERZA CON LOS ESTÁNDARES Y DISPOSICIONES ESTABLECIDAS EN EL PRESENTE DECRETO LEGISLATIVA:', 'EL MINISTERIO DEL INTERIOR', 'DISP. COMP. FIN, TERCERA DISPOSICIÓN', '184762'),
    (2243, 'SUB-2243', 'SBM4', 'LAS DISPOSICIONES DEL PRESENTE DECRETO LEGISLATIVO SE INTERPRETAN CONFORME A LO ESTABLECIDO EN:', 'LA CONSTITUCIÓN POLÍTICA DEL PERÚ.', 'ART. 5', '184763'),
    (2244, 'SUB-2244', 'SBM4', 'LAS DISPOSICIONES DEL PRESENTE DECRETO LEGISLATIVO SE INTERPRETAN CONFORME A LO ESTABLECIDO EN:', 'LAS NORMAS DEL DERECHO INTERNACIONAL DE LOS DERECHOS HUMANOS RECONOCIDAS POR EL ESTADO PERUANO.', 'ART. 5 Decreto Legislativo N°1186 - Ley que Regula el Uso de la Fuerza por Parte de la PNP y su Reglamento', '184764'),
    (2245, 'SUB-2245', 'SBM4', 'LAS DISPOSICIONES DEL PRESENTE DECRETO LEGISLATIVO SE INTERPRETAN CONFORME A LO ESTABLECIDO EN:', 'LAS DECISIONES DE ORGANISMOS SUPRANACIONALES.', 'ART. 5', '184765'),
    (2246, 'SUB-2246', 'SBM4', 'LAS DISPOSICIONES DEL PRESENTE DECRETO LEGISLATIVO SE INTERPRETAN CONFORME A LO ESTABLECIDO EN:', 'LOS PRINCIPIOS BÁSICOS SOBRE EL EMPLEO DE LA FUERZA Y DE ARMAS DE FUEGO POR LOS FUNCIONARIOS ENCARGADOS DE HACER CUMPLIR LA LEY.', 'ART. 5', '184766'),
    (2247, 'SUB-2247', 'SBM4', 'LAS DISPOSICIONES DEL PRESENTE DECRETO LEGISLATIVO SE INTERPRETAN CONFORME A LO ESTABLECIDO EN:', 'EL CÓDIGO DE CONDUCTA PARA FUNCIONARIOS ENCARGADOS DE HACER CUMPLIR LA LEY.', 'ART. 5', '184767'),
    (2248, 'SUB-2248', 'SBM4', 'SEGÚN LO ESTABLECIDO EN EL DECRETO LEGISLATIVO QUE REGULA EL USO DE LA FUERZA POR PARTE DE LA POLICÍA NACIONAL DEL PERÚ, LA FUERZA DEBE USARSE:', 'DE MANERA PROGRESIVA Y DIFERENCIADA, DE CONFORMIDAD CON LOS PRINCIPIOS Y LOS NIVELES ESTABLECIDOS EN EL PRESENTE DECRETO LEGISLATIVO.', 'ART. 6', '184768'),
    (2249, 'SUB-2249', 'SBM4', 'PRINCIPIO DE NECESIDAD. EL USO DE LA FUERZA EN EL CUMPLIMIENTO DEL DEBER ES NECESARIO:', 'CUANDO OTROS MEDIOS RESULTEN INEFICACES O NO GARANTICEN DE NINGUNA MANERA EL LOGRO DEL OBJETIVO LEGAL BUSCADO.', 'ART. 4 LIT. B', '184769'),
    (2250, 'SUB-2250', 'SBM4', '¿EN QUÉ CIRCUNSTANCIA, SE DISPONE LA INVESTIGACIÓN ADMINISTRATIVA CORRESPONDIENTE Y SE DA INMEDIATA CUENTA DE LOS HECHOS A LAS AUTORIDADES COMPETENTES PARA LOS FINES CONSIGUIENTES:', 'CUANDO AL USAR LA FUERZA SE OCASIONARA LESIONES O MUERTE.', 'ART. 11, 11.2', '184770'),
    (2251, 'SUB-2251', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL NO PUEDE ALEGAR OBEDIENCIA A ÓRDENES SUPERIORES SI TENÍA CONOCIMIENTO QUE EL USO DE ÉSTA ERA MANIFIESTAMENTE ILÍCITA, CUANDO:', 'SE USEN LAS ARMAS DE FUEGO.', 'ART. 11, 11.3', '184771'),
    (2252, 'SUB-2252', 'SBM4', 'CUANDO SE USEN LAS ARMAS DE FUEGO, EL PERSONAL DE LA POLICÍA NACIONAL NO PUEDE ALEGAR OBEDIENCIA A ÓRDENES SUPERIORES SI TENÍA CONOCIMIENTO QUE EL USO DE ÉSTA ERA MANIFIESTAMENTE ILÍCITA. EN CASO DE HABERSE EJECUTADO, TAMBIÉN SERÁN RESPONSABLES:', 'LOS SUPERIORES QUE DIERON DICHAS ÓRDENES.', 'ART. 11, 11.3', '184772'),
    (2253, 'SUB-2253', 'SBM4', 'LOS SUPERIORES JERÁRQUICOS INCURREN EN RESPONSABILIDAD CUANDO CONOZCAN O DEBIENDO CONOCER DEL USO ILÍCITO DE LA FUERZA POR EL PERSONAL POLICIAL A SUS ÓRDENES, NO ADOPTEN:', 'LAS MEDIDAS NECESARIAS PARA IMPEDIR O NEUTRALIZAR DICHO USO O NO DENUNCIARON EL HECHO OPORTUNAMENTE.', 'ART. 11, 11.4', '184773'),
    (2254, 'SUB-2254', 'SBM4', 'EL USO DE LA FUERZA QUE CONTRAVENGA EL DECRETO LEGISLATIVO, GENERA:', 'RESPONSABILIDAD ADMINISTRATIVA DISCIPLINARIA, PENAL Y CIVIL.', 'ART. 11, 11.5 Decreto Legislativo N°1186 - Ley que Regula el Uso de la Fuerza por Parte de la PNP y su Reglamento', '184774'),
    (2255, 'SUB-2255', 'SBM4', 'EN EL PRINCIPIO DE NECESIDAD, PARA DETERMINAR EL NIVEL DE FUERZA A USAR, SE DEBE CONSIDERAR, RAZONABLEMENTE, ENTRE OTRAS CIRCUNSTANCIAS EL NIVEL DE:', 'COOPERACION, RESISTENCIA O AGRESIÓN DE LA PERSONA INTERVENIDA', 'ART. 4 LIT. B', '184775'),
    (2256, 'SUB-2256', 'SBM4', 'EN EL PRINCIPIO DE NECESIDAD, PARA DETERMINAR EL NIVEL DE FUERZA A USAR, SE DEBE CONSIDERAR, RAZONABLEMENTE, ENTRE OTRAS CIRCUNSTANCIAS, EL NIVEL DE:', 'LAS CONDICIONES DEL ENTORNO.', 'ART. 4 LIT. B', '184776'),
    (2257, 'SUB-2257', 'SBM4', 'PRINCIPIOS. EL USO DE LA FUERZA POR PERSONAL DE LA POLICÍA NACIONAL, SE SUSTENTA EN:', 'EL RESPETO DE LOS DERECHOS FUNDAMENTALES Y LA CONCURRENCIA DE SUS PRINCIPIOS.', 'ART. 4, 4.1', '184777'),
    (2258, 'SUB-2258', 'SBM4', 'LEGALIDAD. LOS MEDIOS Y MÉTODOS UTILIZADOS EN CUMPLIMIENTO DEL DEBER DEBEN ESTAR AMPARADOS EN EL MARCO DEL:', 'DERECHO INTERNACIONAL DE LOS DERECHOS HUMANOS.', 'ART. 4, 4.1, LIT. A', '184778'),
    (2259, 'SUB-2259', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ USAR EL ARMA DE FUEGO CUANDO:', 'SEA ESTRICTAMENTE NECESARIO Y SOLO CUANDO LAS MEDIDAS MENOS EXTREMAS RESULTEN INSUFICIENTES O SEAN INADECUADAS.', 'ART. 8, 8.3', '184779'),
    (2260, 'SUB-2260', 'SBM4', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, EXCEPCIONALMENTE, PODRÁ USAR EL ARMA DE FUEGO CUANDO SEA ESTRICTAMENTE NECESARIO Y:', 'SOLO CUANDO MEDIDAS MENOS EXTREMAS, RESULTEN INSUFICIENTES O SEAN INADECUADAS.', 'ART. 8, 8.3', '184780'),
    (2261, 'SUB-2261', 'SBM4', 'CON POSTERIORIDAD AL USO DE LA FUERZA, QUE DOCUMENTO DEBE PRESENTAR EL PERSONAL DE LA POLICÍA NACIONAL:', 'UN INFORME A LA UNIDAD POLICIAL CORRESPONDIENTE.', 'ART. 9, LIT. C', '184781'),
    (2262, 'SUB-2262', 'SBM4', 'NO ACATAR DISPOSICIONES U ÓRDENES SUPERIORES PARA EL USO DE LA FUERZA CUANDO ESTAS SEAN MANIFIESTAMENTE ILÍCITAS O ARBITRARIAS, ES:', 'UN DERECHO.', 'ART. 10 LIT. B', '184782'),
    (2263, 'SUB-2263', 'SBM4', 'RECIBIR FORMACIÓN, CAPACITACIÓN Y ENTRENAMIENTO PERMANENTE SOBRE EL USO DE LA FUERZA EN TODOS LOS NIVELES EDUCATIVOS CONFORME A LOS ESTÁNDARES NACIONALES E INTERNACIONALES EN MATERIAS DE DERECHOS HUMANOS, ES:', 'UN DERECHO.', 'ART. 10 LIT. C', '184783'),
    (2264, 'SUB-2264', 'SBM4', 'RECIBIR TRATAMIENTO Y ASISTENCIA MÉDICA, POR CUENTA DEL ESTADO CUANDO RESULTE AFECTADO EN CUMPLIMIENTO DE SU DEBER, ES:', 'UN DERECHO.', 'ART. 10 LIT. E', '184784'),
    (2265, 'SUB-2265', 'SBM4', 'ACATA TODAS LAS INDICACIONES DEL EFECTIVO POLICIAL SIN RESISTENCIA MANIFIESTA DURANTE LA INTERVENCIÓN, CORRESPONDE A LA DEFINICIÓN DE:', 'COOPERADOR.', 'ART. 7, 7.1 LIT. A, NUM. 2', '184785'),
    (2266, 'SUB-2266', 'SBM4', 'ENTENDIDA COMO DEMOSTRACIÓN DE AUTORIDAD DEL PERSONAL DE LA POLICÍA NACIONAL UNIFORMADO, EQUIPADO, EN ACTITUD DE ALERTA Y REALIZANDO UN CONTROL VISUAL, QUE PREVIENE Y DISUADE LA COMISIÓN DE UNA INFRACCIÓN O UN DELITO. CORRESPONDE A LA DEFINICION DE:', 'PRESENCIA POLICIAL.', 'ART. 7, 7.2 LIT. A, NUM 1', '184786'),
    (2267, 'SUB-2267', 'SBM4', 'ES EL USO DE LA COMUNICACIÓN ORAL CON LA ENERGÍA NECESARIA Y EL USO DE TÉRMINOS ADECUADOS QUE SEAN FÁCILMENTE ENTENDIDOS Y COMPRENDIDOS POR LAS PERSONAS A INTERVENIR, FACILITANDO SU CONTROL INDIVIDUAL O GRUPAL. CORRESPONDE A LA DEFINICIÓN DE:', 'VERBALIZACION.', 'ART. 7, 7.2 LIT. A, NUM. 2', '184787'),
    (2268, 'SUB-2268', 'SBM4', 'LOS NIVELES DE USO DE LA FUERZA TANTO EN LA RESISTENCIA PASIVA COMO ACTIVA, SON LOS SIGUIENTES: (MARQUE LA QUE NO CORRESPONDE):', 'AGRESIÓN FÍSICA.', 'ART. 7', '184788'),
    (2269, 'SUB-2269', 'SBM4', 'ES EL USO DE ARMAS DE FUEGO POR EL PERSONAL DE LA POLICÍA NACIONAL, CONTRA QUIÉN REALIZA UNA ACCIÓN QUE REPRESENTA UN PELIGRO REAL E INMINENTE DE MUERTE O LESIONES GRAVES. CORRESPONDE A LA DEFINICIÓN DE:', 'FUERZA LETAL.', 'ART. 7, 7.2 LIT. B. NUM. 3', '184789'),
    (2270, 'SUB-2270', 'SBM4', 'ESTABLECE EL MARCO LEGAL QUE REGULA EL USO DE LA FUERZA POR PARTE DEL PERSONAL DE LA PNP EN CUMPLIMIENTO DE SU FINALIDAD CONSTITUCIONAL, CORRESPONDE A:', 'OBJETO.', 'ART. 1', '184790'),
    (2271, 'SUB-2271', 'SBM4', 'EL FORTALECER LA LUCHA CONTRA EL TRAFICO ILICITO DE DROGAS - TID EN SUS DIVERSAS MANIFESTACIONES, MEDIANTE LA PREVENCIÓN, INVESTIGACIÓN Y COMBATE DE DICHO DELITO; ASÍ COMO EL APOYO A LA REDUCCIÓN DE LOS CULTIVOS ILEGALES DE HOJA DE COCA. CORRESPONDE A:.', 'OBJETO', 'ART. 1', '184950'),
    (2272, 'SUB-2272', 'SBM4', '¿QUIÉN CONDUCE Y ARTICULA LA POLÍTICA NACIONAL CONTRA LAS DROGAS CON LOS SECTORES E INSTITUCIONES EN LA LUCHA CONTRA EL TID, CONFORME A LEY?.', 'DEVIDA', 'ART. 2.1', '184951'),
    (2273, 'SUB-2273', 'SBM4', '¿QUIÉN CONDUCE Y SUPERVISA LAS POLÍTICAS SECTORIALES EN MATERIA DE LUCHA CONTRA LAS DROGAS, INSUMOS QUÍMICOS Y PRODUCTOS FISCALIZADOS DECOMISADOS POR TRÁFICO ILÍCITO DE DROGAS, ERRADICACIÓN DE LOS CULTIVOS ILEGALES Y DESTRUCCIÓN DE DROGAS ILEGALES DECOMISADAS?.', 'MINISTERIO DEL INTERIOR.', 'ART. 2, NUM.2.2', '184952'),
    (2274, 'SUB-2274', 'SBM4', '¿QUIÉNES TIENEN LA OBLIGACIÓN DE COADYUVAR CON LAS AUTORIDADES COMPETENTES EN LA LUCHA CONTRA EL TRÁFICO ILÍCITO DE DROGAS - TID?.', 'TODAS LAS PERSONAS NATURALES, JURÍDICAS E INSTITUCIONES PÚBLICAS Y PRIVADAS.', 'ART. 2, NUM.2.4', '184953'),
    (2275, 'SUB-2275', 'SBM4', '¿QUÉ ACCIONES A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LA POLICÍA NACIONAL DEL PERÚ?. MARQUE LA RESPUESTA CORRECTA :.', 'APOYAR A LA SUPERINTENDENCIA NACIONAL DE ADUANAS Y DE ADMINISTRACIÓN TRIBUTARIA - SUNAT EN LA LABOR DE VERIFICACIÓN Y CERTIFICACIÓN DE LA EXISTENCIA DE CONDICIONES O CONTROLES MÍNIMOS DE SEGURIDAD SOBRE LAS SUSTANCIAS QUÍMICAS CONTROLADAS', 'ART. 3, NUM.3.2.4', '184954'),
    (2276, 'SUB-2276', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ A TRAVES DE SUS UNIDADES ESPECIALIZADAS ANTIDROGAS REALIZAN OPERACIONES POLICIALES:.', 'PREVENTIVAS, DISUASIVAS Y DE CONTROL.', 'ART. 3, NUM.3.1.1', '184955'),
    (2277, 'SUB-2277', 'SBM4', 'EN EL ÁMBITO DE LA INTERDICCIÓN, LA POLICÍA NACIONAL DEL PERÚ APOYA LA PRÁCTICA DE ACTIVIDADES DE SENSIBILIZACIÓN COLECTIVA DIRIGIDA A:.', 'LOS SEGMENTOS VULNERABLES DE LA SOCIEDAD.', 'ART. 3, NUM.3.1.2', '184956'),
    (2278, 'SUB-2278', 'SBM4', 'A TRAVÉS DE SU DEPENDENCIA ESPECIALIZADA, ES LA AUTORIDAD ADMINISTRATIVA A CARGO DEL CONTROL Y FISCALIZACIÓN DE SUSTANCIAS QUÍMICAS EMPLEADAS LEGALMENTE EN LA INDUSTRIA FARMACÉUTICA Y QUE PUEDEN SER SUSCEPTIBLES DE UTILIZACIÓN EN LOS PROCESOS DE ELABORACIÓN ILEGAL DE ESTUPEFACIENTES Y SUSTANCIAS PSICOTRÓPICAS:.', 'MINISTERIO DE SALUD.', 'ART. 11', '184957'),
    (2279, 'SUB-2279', 'SBM4', 'LAS ACCIONES DE PREVENCIÓN QUE REALIZA LA POLICÍA NACIONAL DEL PERÚ A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, CON LA FINALIDAD DE EVITAR EL DESVIÓ DE SUSTANCIAS QUÍMICAS O EL TRÁFICO ILÍCITO DE INSUMOS QUÍMICOS Y PRODUCTOS FISCALIZADOS (IQPF) HACIA EL TRÁFICO ILÍCITO DE DROGAS - TID, TIENEN CARÁCTER:.', 'SELECTIVO', 'ART. 3, NUM.3.2.3', '184958'),
    (2280, 'SUB-2280', 'SBM4', '¿QUÉ SANCIÓN ES APLICABLE CUANDO LA POLICÍA NACIONAL DEL PERÚ A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, RETIENE TEMPORALMENTE SUSTANCIAS QUÍMICAS Y MEDIOS DE TRANSPORTE, POR REPRESENTAR INFRACCIONES A LAS LEYES DE CONTROL Y FISCALIZACIÓN?:.', 'INCAUTACIÓN', 'ART. 3, NUM.3.2.5', '184959'),
    (2281, 'SUB-2281', 'SBM4', '¿CON QUÉ AUTORIDADES DEBERÁ DE COORDINAR LA POLICÍA NACIONAL, PARA LA DESTRUCCIÓN E INHABILITACIÓN DE PISTAS DE ATERRIZAJE CLANDESTINAS, UTILIZADAS PARA EL TRANSPORTE ILEGAL DE DROGAS TÓXICAS, ESTUPEFACIENTES O SUSTANCIAS PSICOTRÓPICAS?:.', 'MINISTERIO DE TRANSPORTES Y COMUNICACIONES O GOBIERNOS REGIONALES.', 'ART. 3, NUM.3.2.6', '184960'),
    (2282, 'SUB-2282', 'SBM4', 'LA POLICÍA NACIONAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, PARA LA DESTRUCCIÓN O NEUTRALIZACIÓN SEGÚN SEA EL CASO INSTALACIONES RÚSTICAS, FÁBRICAS O LABORATORIOS DE ELABORACIÓN ILEGAL DE DROGAS TÓXICAS COCAÍNITAS, ESTUPEFACIENTES O SUSTANCIAS PSICOTRÓPICAS, CULTIVOS DE PLANTAS DE AMAPOLA O ADORMIDERA DE LA ESPECIE PAPAVER SOMNÍFERUM O DE MARIHUANA DE LA ESPECIE CANNABIS SATIVA, SUSTANCIAS QUÍMICAS, MATERIA PRIMA, MATERIALES E IMPLEMENTOS QUE SE EMPLEAN EN LA ELABORACIÓN DE LAS INDICADAS DROGAS, ADOPTA LAS MEDIDAS ORIENTADAS A:.', 'MINIMIZAR EL IMPACTO AMBIENTAL.', 'ART. 3, NUM.3.2.8', '184961'),
    (2283, 'SUB-2283', 'SBM4', '¿QUIÉN AUTORIZA LA DESTRUCCIÓN O INUTILIZACIÓN DE LOS MEDIOS DE TRANSPORTE TERRESTRE, ACUÁTICO O AÉREO QUE SE EMPLEEN O SE PRETENDA EMPLEAR PARA EL TRASLADO DE DROGAS TÓXICAS Y OTRAS SUSTANCIAS ILEGALES?. MARQUE LA RESPUESTA CORRECTA:.', 'MINISTERIO PÚBLICO.', 'ART. 3, NUM.3.2.9', '184962'),
    (2284, 'SUB-2284', 'SBM4', '¿QUÉ ENTIDAD RECEPCIONA LA CONSOLIDACIÓN DE ESTADÍSTICA SOBRE CONTEO DE PLANTAS REMITIDA POR LA DIRANDRO DE LA POLICÍA NACIONAL DEL PERÚ?:.', 'DEVIDA', 'ART. 3, NUM.3.2.11', '184963'),
    (2285, 'SUB-2285', 'SBM4', '¿QUÉ SE PUEDE EVITAR EN LA DESACTIVACIÓN DE LABORATORIOS CLANDESTINOS DE ELABORACIÓN DE DROGAS SINTÉTICAS?, CUANDO SE ADOPTAN LAS MEDIDAS DE SEGURIDAD, EMPLEANDO MANUALES, PROTOCOLOS O GUÍAS DE TRABAJO DE NATURALEZA LOCAL O INTERNACIONAL:.', 'CONSECUENCIAS SOBRE LAS PERSONAS Y EL MEDIO AMBIENTE.', 'ART. 3.2.10', '184964'),
    (2286, 'SUB-2286', 'SBM4', '¿QUÉ DEBE DE CONSIGNAR LA POLICÍA NACIONAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, EN EL LUGAR DE INTERVENCIÓN, AL LEVANTAR LAS ACTAS EN LAS DILIGENCIAS PARA LA DESTRUCCIÓN, INHABILITACIÓN, INUTILIZACIÓN, NEUTRALIZACIÓN, DESACTIVACIÓN U OTRAS?:.', 'POSICIÓN GEO-REFERENCIAL', 'ART. 3, NUM.3.2.11', '184965'),
    (2287, 'SUB-2287', 'SBM4', '¿QUÉ IMPLICA PARA LA LUCHA CONTRA EL TRÁFICO ILÍCITO DE DROGAS - TID, LA CUANTIFICACIÓN DE LOS CULTIVOS?. MARQUE LA RESPUESTA CORRECTA:.', 'EL CONTEO DE PLANTAS.', 'ART. 3, NUM.3.2.11', '184966'),
    (2288, 'SUB-2288', 'SBM4', '¿DÓNDE SE PROHÍBE EL CULTIVO DE COCA Y ALMÁCIGOS?. MARQUE LA RESPUESTA CORRECTA:.', 'EN ÁREAS NO EMPADRONADAS POR LA AUTORIDAD COMPETENTE.', 'ART. 4, NUM. 4.1', '184967'),
    (2289, 'SUB-2289', 'SBM4', 'DE ACUERDO A LAS METAS PLANTEADAS ANUALMENTE, LAS PLANTACIONES DE COCA ILEGALMENTE CULTIVADAS SON:.', 'OBJETO DE ERRADICACIÓN.', 'ART. 4, NUM. 4.2', '184968'),
    (2290, 'SUB-2290', 'SBM4', 'MEDIANTE QUE NORMA, SE PUEDE INCORPORAR LA PROHIBICIÓN DE CULTIVO DE OTRAS PLANTAS O ESPECIES PROHÍBIDAS:.', 'DECRETO SUPREMO.', 'ART. 5', '184969'),
    (2291, 'SUB-2291', 'SBM4', 'LA INDUSTRIALIZACIÓN COMPRENDE LA ELABORACIÓN DE PASTA BÁSICA DE COCAÍNA, CLORHÍDRATO DE COCAÍNA Y DEMÁS DERIVADOS DE LA HOJA DE COCA DE PRODUCCIÓN LÍCITA CON:.', 'FINES BENÉFICOS.', 'ART. 6, NUM.6.2', '184970'),
    (2292, 'SUB-2292', 'SBM4', 'LA POSESIÓN Y COMERCIALIZACIÓN ILEGAL DE HOJA DE COCA ES SANCIONADA CON:.', 'LA INCAUTACIÓN DEL PRODUCTO.', 'ART. 6, NUM.6.3', '184971'),
    (2293, 'SUB-2293', 'SBM4', 'LOS CULTIVOS DE PLANTAS DE AMAPOLA O ADORMIDERA DE LA ESPECIE PAPAVER SOMNÍFERUM O DE MARIHUANA DE LA ESPECIE CANNABIS SATIVA SON DESTRUIDOS IN SITU POR LA:.', 'POLICÍA NACIONAL DEL PERÚ CON INTERVENCIÓN DEL MINISTERIO PÚBLICO.', 'ART. 7', '184972'),
    (2294, 'SUB-2294', 'SBM4', 'LOS CULTIVOS DE PLANTAS DE AMAPOLA O ADORMIDERA DE LA ESPECIE PAPAVER SOMNÍFERUM O DE MARIHUANA DE LA ESPECIE CANNABIS SATIVA SON DESTRUÍDOS IN SITU, LEVANTÁNDOSE EL ACTA CORRESPONDIENTE, INDICANDO:.', 'LA', 'ART. 7', '184973'),
    (2295, 'SUB-2295', 'SBM4', '¿QUÉ REGISTROS LEVANTA LA AUTORIDAD COMPETENTE DEL GOBIERNO CENTRAL, REGIONAL O LOCAL, EN ÁREAS DE CULTIVO DE SU DEMARCACIÓN, QUE SIRVE PARA IDENTIFICAR A LOS PROPIETARIOS O POSESIONARIOS DE LOS TERRENOS DONDE SE PUEDAN DESCUBRIR CULTIVOS ILEGALES DE COCA EN RESIEMBRA, AMAPOLA O ADORMIDERA DE LA ESPECIE PAPAVER SOMNÍFERUM O DE MARIHUANA DE LA ESPECIE CANNABIS SATIVA? MARQUE LA RESPUESTA CORRECTA:.', 'CATASTRALES Y TOPOGRÁFICOS.', 'ART. 9', '184974'),
    (2296, 'SUB-2296', 'SBM4', '¿QUÉ REGISTROS LEVANTA LA AUTORIDAD COMPETENTE DEL GOBIERNO CENTRAL, REGIONAL O LOCAL, EN ÁREAS DE CULTIVO DE SU DEMARCACIÓN, QUE SIRVE PARA IDENTIFICAR A LOS PROPIETARIOS O POSESIONARIOS DE LOS TERRENOS, EN DONDE EXISTAN LABORATORIOS RÚSTICOS DE ELABORACIÓN DE DROGAS Y PISTAS DE ATERRIZAJE CLANDESTINAS? MARQUE LA RESPUESTA CORRECTA:.', 'CATASTRALES Y TOPOGRÁFICOS.', 'ART. 9', '184975'),
