INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 2301 a 2400
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (2301, 'SUB-2301', 'SBM4', 'INCAUTACIONES Y DECOMISOS.- SON OBJETO DE INCAUTACIÓN LOS SIGUIENTES BIENES:.', 'LOS BIENES MUEBLES E INMUEBLES, TALES COMO VEHÍCULOS, NAVES, ARTEFACTOS NAVALES O AÉREOS, AERONAVES Y SEMOVIENTES O SOPORTES EMPLEADOS COMO MEDIOS O INSTRUMENTOS PARA FACILITAR LA COMISIÓN DEL DELITO.', 'ART. 12.2 LIT.C', '184980'),
    (2302, 'SUB-2302', 'SBM4', '¿QUE SE EVALÚA PARA LA INCAUTACIÓN DE INMUEBLES, VEHÍCULOS, DINERO U OTROS VALORES?.', 'LA VINCULACIÓN CON LOS PRESUNTOS AUTORES O PARTICIPES.', 'ART. 12, NUM. 12.3', '184981'),
    (2303, 'SUB-2303', 'SBM4', '¿QUÉ AUTORIDAD PUEDE DISPONER LA INMOVILIZACIÓN DE BIENES MUEBLES, COMO MEDIDA TRANSITORIA EN CASO DE FLAGRANCIA, CON LA FINALIDAD DE ASEGURAR LA PERMANENCIA Y CUSTODIA EN EL LUGAR QUE SE ENCUENTREN?. D.L. 1241 - Ley que fortalece la lucha Contra el TID', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 12, NUM. 12.4', '184982'),
    (2304, 'SUB-2304', 'SBM4', 'LUEGO DE LOS EXÁMENES PRACTICADOS, ¿DÓNDE SON INTERNADAS LAS DROGAS DECOMISADAS?.', 'EN LOS ALMACENES DE LA DIRECCIÓN GENERAL CONTRA EL CRIMEN ORGANIZADO O QUIEN HAGA SUS VECES', 'ART. 13, NUM. 13.1', '184983'),
    (2305, 'SUB-2305', 'SBM4', '¿QUÉ PROCEDIMIENTO DEBE SER PRACTICADO EN ACTO PÚBLICO POR UN PROFESIONAL QUÍMICO CON LAS DROGAS DECOMISADAS, ANTES DE SU INCINERACIÓN?', 'PESAJE Y ANÁLISIS.', 'ART. 13, NUM. 13.1', '184984'),
    (2306, 'SUB-2306', 'SBM4', '¿QUÉ AUTORIDADES SE ENCUENTRAN PRESENTES PARA LA DESTRUCCIÓN POR INCINERACIÓN, NEUTRALIZACIÓN, TRANSFORMACIÓN NO RECUPERABLE U OTRO MÉTODO SEGURO REALIZADO EN ACTO PÚBLICO ORGANIZADO POR LA DIRECCIÓN GENERAL CONTRA EL CRIMEN ORGANIZADO DEL MINISTERIO DEL INTERIOR PARA LA INCINERACIÓN DE LAS DROGAS DECOMISADAS?:.', 'REPRESENTANTES DEL MINISTRO DEL INTERIOR Y DE LA FISCALÍA DE LA NACIÓN', 'ART. 13, NUM. 13.1', '184985'),
    (2307, 'SUB-2307', 'SBM4', '¿QUÉ DISPONE EL MINISTERIO PÚBLICO CON LOS OBJETOS EMPLEADOS, COMO ESCONDITE DE DROGAS (RECIPIENTES, MALETAS, ENTRE OTROS), LUEGO DEL EXAMEN O REGISTRO MATERIAL Y PERICIAL, ASÍ COMO DE LA DEBIDA PERENNIZACIÓN Y ELIMINACIÓN DE TODOS LOS RESTOS Y ADHERENCIAS DE DROGAS?:.', 'SU DESTRUCCIÓN O INUTILIZACIÓN.', 'ART. 13.3', '184986'),
    (2308, 'SUB-2308', 'SBM4', '¿DÓNDE SON PUESTOS A DISPOSICIÓN LOS BIENES MUEBLES E INMUEBLES SOBRE LOS CUALES HAYA RECAÍDO MEDIDA DE INCAUTACIÓN?.', 'PRONABI', 'ART. 13, NUM. 13.4', '184987'),
    (2309, 'SUB-2309', 'SBM4', '¿DÓNDE SON DEPOSITADOS O INTERNADOS EL DINERO Y JOYAS SOBRE LOS CUALES HAYA RECAÍDO MEDIDA DE INCAUTACIÓN?.', 'BANCO DE LA NACIÓN.', 'ART. 13, NUM. 13.4', '184988'),
    (2310, 'SUB-2310', 'SBM4', 'DESTINO DE LOS OBJETOS DECOMISADOS O INCAUTADOS.- LOS SEMOVIENTES SOBRE LOS CUALES HAYA RECAÍDO MEDIDA DE INCAUTACIÓN, QUEDAN EN PODER DE:.', 'AUTORIDADES LOCALES.', 'ART. 13, NUM. 13.4', '184989'),
    (2311, 'SUB-2311', 'SBM4', '¿DÓNDE SON INTERNADAS LAS ARMAS, MUNICIONES Y SIMILARES, SOBRE LAS QUE HAYA RECAÍDO LA MEDIDA DE INCAUTACIÓN?:.', 'SUCAMEC', 'ART. 13, NUM. 13.4', '184990'),
    (2312, 'SUB-2312', 'SBM4', '¿DÓNDE SON PUESTAS A DISPOSICIÓN LAS AERONAVES SOBRE LAS CUALES HAYA RECAÍDO MEDIDA DE INCAUTACIÓN?:.', 'DIRECCIÓN AÉREA ESPECIALIZADA DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 13, NUM. 13.4', '184991'),
    (2313, 'SUB-2313', 'SBM4', '¿DÓNDE SON REGISTRADOS LOS OBJETOS DECOMISADOS CON SENTENCIA JUDICIAL FIRME?.', 'PRONABI', 'ART. 13, NUM. 13.5', '184992'),
    (2314, 'SUB-2314', 'SBM4', '¿QUIÉN PUEDE PRIORIZAR LA AFECTACIÓN EN USO A LA UNIDAD ESPECIALIZADA QUE PRACTICÓ LA INCAUTACIÓN U OTRAS DEL SISTEMA ANTIDROGAS DE LA POLICÍA NACIONAL DEL PERÚ?.', 'PRONABI', 'ART. 13, NUM. 13.5', '184993'),
    (2315, 'SUB-2315', 'SBM4', '¿DÓNDE SE ESPECIFICA LA LISTA DE SUSTANCIAS QUÍMICAS?.', 'EN EL REGLAMENTO DEL DECRETO LEGISLATIVO 1241.', 'ART. 14', '184994'),
    (2316, 'SUB-2316', 'SBM4', 'EN EL DELITO DE TRÁFICO ILÍCITO DE DROGAS, ¿CUÁL ES LA FINALIDAD DE EJECUTAR ACCIONES DE OBSERVACIÓN,VIGILANCIA Y SEGUIMIENTO DE BLANCOS OBJETIVOS O EN TORNO A OBJETOS O INMUEBLES?.', 'REUNIR LOS ELEMENTOS DE CONVICCIÓN SUFICIENTES.', 'ART. 15, LIT.B', '184995'),
    (2317, 'SUB-2317', 'SBM4', '¿QUÉ ARTÍCULO DEL CÓDIGO PENAL, DETERMINA LA SANCIÓN RESPECTO A LA CUANTIFICACIÓN DE CULTIVOS PARA LA ELABORACIÓN DE DROGAS ILEGALES?:.', 'ARTÍCULO 296-A.', 'ART. 3.2.11', '184996'),
    (2318, 'SUB-2318', 'SBM4', 'CON LA FINALIDAD DE PRACTICAR ANÁLISIS DE LA INFORMACIÓN PARA FINES DE PERFILACIÓN DE RIESGOS O PELIGRO INMINENTE DE DESVÍO DE INSUMOS O SUSTANCIAS QUÍMICAS DESTINADAS A LA ELABORACIÓN ILEGAL DE DROGAS, ¿QUIÉN TIENE ACCESO EN LÍNEA Y EN TIEMPO REAL, A LA INFORMACIÓN DEL REGISTRO DE BIENES FISCALIZADOS QUE ADMINISTRA SUNAT?.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 3.3', '184997'),
    (2319, 'SUB-2319', 'SBM4', 'LAS PLANTACIONES DE COCA ILEGALMENTE CULTIVADAS SON OBJETO DE ERRADICACIÓN DE ACUERDO A LAS METAS PLANTEADAS:.', 'ANUALMENTE', 'ART. 4, NUM.4.2', '184998'),
    (2320, 'SUB-2320', 'SBM4', 'CULTIVOS PROHIBIDOS.- ¿MEDIANTE QUE NORMA LEGAL SE PUEDE INCORPORAR OTRAS PLANTAS O ESPECIES PROHIBIDAS?. D.L. 1241 - Ley que fortalece la lucha Contra el TID', 'MEDIANTE DECRETO SUPREMO, A PROPUESTA DEL MINISTERIO DEL INTERIOR O EN FORMA CONJUNTA CON SECTORES O INSTITUCIONES COMPETENTES', 'ART. 5', '184999'),
    (2321, 'SUB-2321', 'SBM4', '¿EL ESTADO A TRAVÉS DE QUIÉN REALIZA EXCLUSIVAMENTE LA INDUSTRIALIZACIÓN Y COMERCIALIZACIÓN INTERNA Y EXTERNA DE LA HOJA DE COCA PROVENIENTE DE LOS PREDIOS EMPADRONADOS?.', 'ENACO S.A.', 'ART. 6.1', '185000'),
    (2322, 'SUB-2322', 'SBM4', '¿QUE COMPRENDE LA ELABORACIÓN DE PASTA BÁSICA DE COCAÍNA, CLORHIDRATO DE COCAÍNA Y DEMÁS DERIVADOS DE LA HOJA DE COCA DE PRODUCCIÓN LÍCITA CON FINES BENÉFICOS?.', 'LA INDUSTRIALIZACIÓN.', 'ART. 6.2', '185001'),
    (2323, 'SUB-2323', 'SBM4', 'LAS INSTALACIONES DEDICADAS AL PROCESAMIENTO DE COCAÍNA EN FASE DE PASTA BÁSICA DE COCAÍNA, SON INCAUTADOS Y AFECTADOS A FAVOR DEL ESTADO Y REGISTRADOS EN:.', 'LA COMISIÓN NACIONAL DE BIENES INCAUTADOS - CONABI.', 'ART. 8', '185002'),
    (2324, 'SUB-2324', 'SBM4', 'EL FUNCIONARIO PÚBLICO QUE APROVECHANDO DE SU CONDICIÓN FACILITA O TOLERA EL USO DE MAQUINARIAS, EQUIPOS O PATRIMONIO PARA REHABILITAR PISTAS CLANDESTINAS DESTRUÍDAS O INHABILITADAS INCURRE EN RESPONSABILIDAD:.', 'PENAL, CIVIL O ADMINISTRATIVA.', 'ART. 10', '185003'),
    (2325, 'SUB-2325', 'SBM4', '¿QUIÉN SUSTENTA LOS PEDIDOS DE LEVANTAMIENTO DEL SECRETO BANCARIO, TRIBUTARIO, BURSÁTIL, ASÍ COMO LAS MEDIDAS LIMITATIVAS DE DERECHO PARA LA DETENCIÓN PREVENTIVA?.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 15, LIT.C', '185004'),
    (2326, 'SUB-2326', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS ES LA ENTIDAD ENCARGADA DE PREVENIR, INVESTIGAR Y COMBATIR EL DELITO DE TRÁFICO ILÍCITO DE DROGAS, EN SUS DIVERSAS MANIFESTACIONES. PARA TAL EFECTO, DESARROLLA LA SIGUIENTE FUNCIÓN: DETENER A LAS PERSONAS EN FLAGRANTE DELITO, POR UN PLAZO:.', 'MÁXIMO DE QUINCE DÍAS NATURALES.', 'ART. 15, LIT.D', '185005'),
    (2327, 'SUB-2327', 'SBM4', '¿QUIÉN DA INICIO A LA CADENA DE CUSTODIA DE EVIDENCIAS, Y DE DROGAS HASTA SU INTERNAMIENTO DEFINITIVO EN LOS ALMACENES DEL MINISTERIO DEL INTERIOR PARA LOS FINES CORRESPONDIENTES?:.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 15, LIT.F', '185006'),
    (2328, 'SUB-2328', 'SBM4', 'ES FUNCIÓN DE LA POLICIA NACIONAL DEL PERÚ EN LA INVESTIGACIÓN Y COMBATE DEL TRÁFICO ILÍCITO DE DROGAS, ASUMIR LA INVESTIGACIÓN DEL DELITO ANTE.', 'NOTICIA CRIMINAL.', 'ART. 15, LIT.G', '185007'),
    (2329, 'SUB-2329', 'SBM4', '¿EJECUTAR ACCIONES DE OBSERVACION, VIGILANCIA Y SEGUIMIENTO DE BLANCOS OBJETIVOS O EN TORNO A OBJETOS O INMUEBLES, CON LA FINALIDAD DE REUNIR LOS ELEMENTOS DE CONVICCIÓN SUFICIENTES, ES FUNCION DE ?.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 15, LIT.B', '185008'),
    (2330, 'SUB-2330', 'SBM4', '¿QUÉ INSTITUCIÓN REALIZA LAS DILIGENCIAS COMPLEMENTARIAS TENIENDO EN CUENTA LA CALIDAD DEL INVESTIGADO EN CUANTO A SU EDAD, GÉNERO, NACIONALIDAD, LIMITACIÓN VISUAL, AUDITIVA O VOCAL, LA INVESTIDURA Y OTROS, QUE MERECEN UNA ACTUACIÓN ESPECIAL Y EN OCASIONES, ADICIONAL?.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 15, LIT.K', '185009'),
    (2331, 'SUB-2331', 'SBM4', '¿LA POLICÍA NACIONAL DEL PERÚ CON AUTORIZACIÓN DE QUE INSTITUCIÓN HACE USO DE LAS TÉCNICAS ESPECIALES DE INVESTIGACIÓN REGULADAS EN EL CÓDIGO PROCESAL PENAL Y LA LEY 30077, LEY CONTRA EL CRIMEN ORGANIZADO?.', 'MINISTERIO PÚBLICO.', 'ART. 17', '185010'),
    (2332, 'SUB-2332', 'SBM4', '¿QUIÉN REALIZA PROCEDIMIENTOS DE CAPTACIÓN DE INFORMANTES Y CONFIDENTES CON LA FINALIDAD DE OBTENER INFORMACIÓN VERAZ Y OPORTUNA QUE PERMITA LA DESARTICULACIÓN DE ORGANIZACIONES CRIMINALES DEDICADAS AL TRÁFICO ILÍCITO DE DROGAS?.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 17', '185011'),
    (2333, 'SUB-2333', 'SBM4', '¿QUIÉN FISCALIZA EL CULTIVO LEGAL DE TODAS LAS VARIEDADES DE COCA?.', 'EL ESTADO.', 'ART. 4.1', '185012'),
    (2334, 'SUB-2334', 'SBM4', '¿QUÉ INSTITUCIÓN EN CUMPLIMIENTO DE SU FUNCIÓN CONSTITUCIONAL DE GARANTIZAR LA INDEPENDENCIA, SOBERANÍA E INTEGRIDAD TERRITORIAL DE LA REPÚBLICA, CONTRIBUYE CON LA POLICÍA NACIONAL DEL PERÚ DURANTE LA EJECUCIÓN DE OPERACIONES POLICIALES DE INTERDICCIÓN AL TRÁFICO ILÍCITO DE DROGAS A PEDIDO DE ESTA CUANDO LAS CIRCUNSTANCIAS EXISTENTES REBASAN LA CAPACIDAD OPERATIVA POLICIAL?.', 'EL EJÉRCITO DEL PERÚ.', 'ART. 18', '185013'),
    (2335, 'SUB-2335', 'SBM4', 'LA SIEMBRA DE NUEVAS PLANTACIONES Y LA RESIEMBRA EN ÁREAS DE CULTIVOS DE COCA ERRADICADOS, SE ENCUENTRA:.', 'PROHIBIDAS', 'ART. 4, NUM. 4.1', '185014'),
    (2336, 'SUB-2336', 'SBM4', 'LA MARINA DE GUERRA DEL PERÚ, EN OBSERVANCIA DE SU MISIÓN CONSTITUCIONAL DE RESGUARDAR LA DEFENSA Y LA SOBERANÍA NACIONAL, DENTRO DE LA JURISDICCIÓN DEL DOMINIO MARÍTIMO DEL ESTADO, EN LOS PUERTOS DEL LITORAL NACIONAL; ASÍ COMO EN LOS PUERTOS FLUVIALES Y LACUSTRES EXISTENTES EN LAS ZONAS DE PRODUCCIÓN COCALERAS O DE ADORMIDERA Y SU ÁREA DE INFLUENCIA, QUE SIRVAN PARA LA ELABORACIÓN ILEGAL DE DROGAS DEL PAÍS, EN APOYO A LA POLICÍA NACIONAL DEL PERÚ; INTERCEPTA EMBARCACIONES NACIONALES O EXTRANJERAS A EFECTO DE ESTABLECER SU IDENTIFICACIÓN Y DESTINO FINAL. SI COMO CONSECUENCIA DE DICHA PARTICIPACIÓN, SE APRECIA INDICIOS DEL DELITO DE TRÁFICO ILÍCITO DE DROGAS, ESTE HECHO ES PUESTO DE INMEDIATO EN CONOCIMIENTO DE:.', 'LA POLICÍA NACIONAL DEL PERÚ Y MINISTERIO PÚBLICO.', 'ART. 19, NUM. 19.1', '185015'),
    (2337, 'SUB-2337', 'SBM4', 'LA ERRADICACIÓN DE LAS PLANTACIONES DE COCA ILEGALMENTE CULTIVADAS, SE REALIZA DE ACUERDO A LAS:.', 'METAS PLANTEADAS ANUALMENTE, Y SE EJECUTA POR EL PROGRAMA ESPECIAL DE ERRADICACIÓN DEL MINISTERIO DEL INTERIOR CON EL APOYO DE LA POLICIA NACIONAL.', 'ART. 4.2', '185016'),
    (2338, 'SUB-2338', 'SBM4', 'LA FUERZA AÉREA DEL PERÚ, EN EL MARCO DE SUS COMPETENCIAS, ESTÁ FACULTADA PARA INTERVENIR O INTERCEPTAR AERONAVES NACIONALES Y EXTRANJERAS QUE SE ENCUENTREN EN LA :.', 'ZONA DE IDENTIFICACIÓN DE DEFENSA AÉREA (ADIZ PERU) O LAS SUPERFICIES SUBYACENTES A ESTA.', 'ART. 20, NUM. 20.1', '185017'),
    (2339, 'SUB-2339', 'SBM4', 'EL CULTIVO DE PLANTAS DE AMAPOLA O ADORMIDERA DE LA ESPECIE PAPAVER SOMNÍFERUM, ASÍ COMO DE MARIHUANA DE LA ESPECIE CANNABIS SATIVA, QUEDA:.', 'PROHIBIDO', 'ART. 5', '185018'),
    (2340, 'SUB-2340', 'SBM4', 'SE INCORPORAN, OTRAS PLANTAS O ESPECIES PROHIBIDAS MEDIANTE DECRETO SUPREMO A PROPUESTA', 'DEL MINISTERIO DEL INTERIOR O EN FORMA CONJUNTA CON SECTORES O INSTITUCIONES COMPETENTES', 'ART. 5', '185019'),
    (2341, 'SUB-2341', 'SBM4', 'EL ESTADO A TRAVÉS DE ENACO S.A. REALIZA EXCLUSIVAMENTE LA INDUSTRIALIZACIÓN Y COMERCIALIZACIÓN DE LA HOJA DE COCA PROVENIENTE DE LOS PREDIOS EMPADRONADOS EN FORMA INTERNA Y:. D.L. 1241 - Ley que fortalece la lucha Contra el TID', 'EXTERNA', 'ART. 6.1', '185020'),
