    (2343, 'SUB-2343', 'SBM4', 'LOS PREDIOS URBANOS O RURALES EN LOS QUE SE ENCUENTREN CULTIVOS DE COCA EN RESIEMBRA O NUEVAS PLANTAS, O PLANTAS DE AMAPOLA O ADORMIDERA DE LA ESPECIE PAPAVER SOMNÍFERUM O DE MARIHUANA DE LA ESPECIE CANNABIS SATIVA SON:', 'INCAUTADOS', 'ART. 8', '185023'),
    (2344, 'SUB-2344', 'SBM4', '¿QUÉ AUTORIDADES LEVANTAN LOS REGISTROS CATASTRALES Y TOPOGRÁFICOS DE LAS ÁREAS DE CULTIVO ILEGALES DE COCA EN RESIEMBRA?.', 'GOBIERNO CENTRAL, GOBIERNO REGIONAL O LOCAL.', 'ART. 9', '185024'),
    (2345, 'SUB-2345', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LAS SIGUIENTES FUNCIONES:', 'INDAGAR, CONSOLIDAR, PROCESAR Y ADMINISTRAR INFORMACIÓN ÚTIL PARA EL INICIO DE LA INVESTIGACIÓN DEL DELITO, EN LA FASE DE ACOPIO DE INFORMACIÓN.', 'ART. 15, LIT.A', '185025'),
    (2346, 'SUB-2346', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LAS SIGUIENTES FUNCIONES:.', 'EJECUTAR ACCIONES DE OBSERVACIÓN, VIGILANCIA Y SEGUIMIENTO DE BLANCOS OBJETIVOS O EN TORNO A OBJETOS O INMUEBLES, CON LA FINALIDAD DE REUNIR LOS ELEMENTOS DE CONVICCIÓN SUFICIENTES, INFORMANDO DE INMEDIATO AL MINISTERIO PÚBLICO.', 'ART. 15, LIT.B', '185026'),
    (2347, 'SUB-2347', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LAS SIGUIENTES FUNCIONES:.', 'SUSTENTAR LOS PEDIDOS DE LEVANTAMIENTO DEL SECRETO BANCARIO, TRIBUTARIO Y BURSÁTIL.', 'ART. 15, LIT.C', '185027'),
    (2348, 'SUB-2348', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LAS SIGUIENTES FUNCIONES:.', 'DETENER A LAS PERSONAS EN FLAGRANTE DELITO, POR UN PLAZO MÁXIMO DE QUINCE DÍAS NATURALES', 'ART. 15, LIT.D', '185028'),
    (2349, 'SUB-2349', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LAS SIGUIENTES FUNCIONES:.', 'EJECUTAR INCAUTACIONES, DECOMISOS, DESTRUCCIONES, NEUTRALIZACIONES, INUTILIZACIONES, REGISTROS, REVELACIÓN Y RECOJO DE EVIDENCIAS.', 'ART. 15, LIT.E', '185029'),
    (2350, 'SUB-2350', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ EN CUMPLIMIENTO DE SU FINALIDAD FUNDAMENTAL A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS, DESARROLLA LAS SIGUIENTES FUNCIONES:.', 'DAR INICIO A LA CADENA DE CUSTODIA DE EVIDENCIAS, Y DE DROGAS HASTA SU INTERNAMIENTO DEFINITIVO.', 'ART. 15, LIT.F', '185030'),
    (2351, 'SUB-2351', 'SBM4', 'EL OBJETO DEL DECRETO LEGISLATIVO QUE FORTALECE LA LUCHA CONTRA EL TRAFICO ILÍCITO DE DROGAS ES:.', 'FORTALECER LA LUCHA CONTRA EL TRAFICO ILÍCITO DE DROGAS - TID EN SUS DIVERSAS MANIFESTACIONES, MEDIANTE LA PREVENCIÓN, INVESTIGACIÓN Y COMBATE DE DICHO DELITO.', 'ART. 1', '185035'),
    (2352, 'SUB-2352', 'SBM4', 'LA COMISIÓN NACIONAL PARA EL DESARROLLO Y VIDA SIN DROGAS - DEVIDA, DISEÑA, COORDINA Y EJECUTA DE MANERA INTEGRAL:....', 'LAS ACCIONES DE PREVENCION CONTRA EL CONSUMO DE DROGAS.', 'ART. 2', '185036'),
    (2353, 'SUB-2353', 'SBM4', 'PREVIENE, INVESTIGA Y COMBATE EL TRÁFICO ILÍCITO DE DROGAS, EN EL MARCO DE SUS FUNCIONES ORIENTADAS A GARANTIZAR EL ORDEN INTERNO.', 'LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 2, NUM.2.3', '185037'),
    (2354, 'SUB-2354', 'SBM4', 'LA POLICÍA NACIONAL DEL PERÚ, A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS ANTIDROGAS, LLEVA LAS SIGUIENTES ACCIONES:.', 'PATRULLA ZONAS DE TRÁNSITO, AÉREAS DE INFLUENCIA Y PUNTOS CRÍTICOS EN EL ÁMBITO NACIONAL.', 'ART. 3, NUM.3.2.1', '185038'),
    (2355, 'SUB-2355', 'SBM4', 'LA MARINA DE GUERRA DEL PERÚ, EN APOYO A LA POLICÍA NACIONAL PERÚ INTERCEPTA EMBARCACIONES NACIONALES O EXTRANJERAS A EFECTO DE ESTABLECER:.', 'SU IDENTIFICACIÓN Y DESTINO FINAL.', 'ART. 19', '185039'),
    (2356, 'SUB-2356', 'SBM4', '¿QUIÉN EFECTÚA ACCIONES DE PREVENCIÓN DE CARACTER SELECTIVO CON LA FINALIDAD DE EVITAR EL DESVÍO DE SUSTANCIAS QUÍMICAS O EL TRÁFICO ILÍCITO DE INSUMOS QUÍMICOS Y PRODUCTOS FISCALIZADOS (IQPF)HACIA EL TID?.', 'LA POLICÍA NACIONAL DEL PERÚ A TRAVÉS DE SUS UNIDADES ESPECIALIZADAS ANTIDROGAS', 'ART. 3, NUM.3.2 LIT.3.2.3', '185040'),
    (2357, 'SUB-2357', 'SBM4', 'USO INDEBIDO DEL PATRIMONIO DEL ESTADO.- ¿QUIÉN INCURRE EN RESPONSABILIDAD PENAL, CIVIL O ADMINISTRATIVA, SEGUN CORRESPONDA?', 'EL FUNCIONARIO PÚBLICO QUE APROVECHANDO DE SU CONDICIÓN FACILITA O TOLERA EL USO DE MAQUINARIAS, EQUIPOS O PATRIMONIO PARA REHABILITAR PISTAS CLANDESTINAS, DESTRUIDAS O INHABILITADAS.', 'ART. 10', '185041'),
    (2358, 'SUB-2358', 'SBM4', 'ES FUNCIÓN DE LA POLICIA NACIONAL DEL PERÚ, REALIZAR LA INVESTIGACION DEL DELITO CON LA CONDUCCION DEL MINISTERIO PÚBLICO. PARA TAL EFECTO:...', 'SE PONE EN PRÁCTICA LOS PROCEDIMIENTOS ESPECIALES DE INVESTIGACIÓN', 'ART. 15, LIT.J', '185042'),
    (2359, 'SUB-2359', 'SBM4', 'LAS UNIDADES ESPECIALIZADAS ANTIDROGAS DE LA POLICÍA NACIONAL DEL PERÚ EN EL AMBITO DE LA INTERDICCIÓN DESARROLLA LAS SIGUIENTES ACCIONES DE PREVENCIÓN DEL DELITO DE TRÁFICO ILÍCITO DE DROGAS:.', 'OPERACIONES POLICIALES PREVENTIVAS, DISUASIVAS Y DE CONTROL.', 'ART. 3, NUM.3.1 LIT.3.1.1', '185043'),
    (2360, 'SUB-2360', 'SBM4', 'EL MINISTERIO DE SALUD, ESTABLECE LAS PROHIBICIONES Y REGULA LAS CONDICIONES EN QUE LOS ESTUPEFACIENTES Y SUSTANCIAS PSICOTRÓPICAS PUEDEN SER ADQUIRIDOS POR LOS USUARIOS FINALES:.', 'COMO AUTORIDAD ADMINISTRATIVA.', 'ART. 11.1', '185044'),
    (2361, 'SUB-2361', 'SBM4', 'EL QUE CONVIERTE O TRANSFIERE DINERO, BIENES, EFECTOS O GANANCIAS CUYO ORIGEN ILÍCITO CONOCE O DEBÍA PRESUMIR, CON LA FINALIDAD DE EVITAR LA IDENTIFICACIÓN DE SU ORIGEN, SU INCAUTACIÓN O DECOMISO; ES CONSIDERADO COMO:.', 'ACTOS DE CONVERSIÓN Y TRANSFERENCIA.', 'ART. 1', '185046'),
    (2362, 'SUB-2362', 'SBM4', 'EL QUE ADQUIERE, UTILIZA, POSEE, GUARDA, ADMINISTRA, CUSTODIA, RECIBE, OCULTA O MANTIENE EN SU PODER DINERO, BIENES, EFECTOS O GANANCIAS, CUYO ORIGEN ILÍCITO CONOCE O DEBÍA PRESUMIR ES CONSIDERADO COMO:.', 'ACTOS DE OCULTAMIENTO Y TENENCIA.', 'ART. 2', '185047'),
    (2363, 'SUB-2363', 'SBM4', 'EL QUE TRANSPORTA O TRASLADA CONSIGO O POR CUALQUIER MEDIO DENTRO DEL TERRITORIO NACIONAL DINERO EN EFECTIVO O INSTRUMENTOS FINANCIEROS NEGOCIABLES EMITIDOS AL PORTADOR; CUYO ORIGEN ILÍCITO CONOCE O DEBÍA PRESUMIR, CON LA FINALIDAD DE EVITAR LA IDENTIFICACIÓN DE SU ORIGEN, SU INCAUTACIÓN O DECOMISO; O HACE INGRESAR O SALIR DEL PAÍS CONSIGO O POR CUALQUIER MEDIO TALES BIENES, CUYO ORIGEN ILÍCITO CONOCE O DEBÍA PRESUMIR, CON IGUAL FINALIDAD; ES CONSIDERADO COMO:.', 'TRANSPORTE, TRASLADO, INGRESO O SALIDA POR TERRITORIO NACIONAL DE DINERO O TÍTULOS VALORES DE ORIGEN ILÍCITO.', 'ART. 3', '185048'),
    (2364, 'SUB-2364', 'SBM4', 'ES UNA CIRCUNSTANCIA AGRAVANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, CUANDO EL AGENTE COMETA EL DELITO EN CALIDAD DE:.', 'INTEGRANTE DE UNA ORGANIZACIÓN CRIMINAL.', 'ART. 4 INC.2', '185049'),
    (2365, 'SUB-2365', 'SBM4', 'ES UNA CIRCUNSTANCIA AGRAVANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, CUANDO EL DINERO, BIENES, EFECTOS O GANANCIAS PROVIENEN DE:.', 'LA MINERÍA ILEGAL.', 'ART. 4 Segundo Párrafo', '185050'),
    (2366, 'SUB-2366', 'SBM4', 'EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, ES UNA CIRCUNSTANCIA AGRAVANTE CUANDO EL DINERO, BIENES, EFECTOS O GANANCIAS PROVIENEN DEL DELITO DE:. DL 1106 - Lucha contra el lavado de activos', 'TRÁFICO ILÍCITO DE DROGAS.', 'ART.4 Segundo Párrafo', '185051'),
    (2367, 'SUB-2367', 'SBM4', 'ES UNA CIRCUNSTANCIA AGRAVANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, CUANDO EL DINERO, BIENES, EFECTOS O GANANCIAS PROVIENEN DE:.', 'TERRORISMO', 'ART.4 Segundo Párrafo', '185052'),
    (2368, 'SUB-2368', 'SBM4', 'ES UNA CIRCUNSTANCIA AGRAVANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, CUANDO EL DINERO, BIENES, EFECTOS O GANANCIAS PROVIENEN DE:.', 'TRATA DE PERSONAS.', 'ART.4 Segundo Párrafo', '185053'),
    (2369, 'SUB-2369', 'SBM4', 'EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, ES UNA CIRCUNSTANCIA AGRAVANTE CUANDO EL DINERO, BIENES, EFECTOS O GANANCIAS PROVIENEN DEL DELITO:', 'EXTORSIÓN', 'ART.4 Segundo Párrafo', '185054'),
    (2370, 'SUB-2370', 'SBM4', 'ES UNA CIRCUNSTANCIA ATENUANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, A QUIEN:.', 'PROPORCIONE A LAS AUTORIDADES INFORMACIÓN EFICAZ PARA EVITAR LA CONSUMACIÓN DEL DELITO.', 'ART. 4 Tercer Párrafo', '185057'),
    (2371, 'SUB-2371', 'SBM4', 'ES UNA CIRCUNSTANCIA ATENUANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, EL QUE PROPORCIONE A LAS AUTORIDADES INFORMACIÓN EFICAZ PARA:.', 'IDENTIFICAR Y CAPTURAR A SUS AUTORES O PARTÍCIPES.', 'ART. 4 Tercer Párrafo', '185058'),
    (2372, 'SUB-2372', 'SBM4', 'ES UNA CIRCUNSTANCIA ATENUANTE EN LA LUCHA EFICAZ CONTRA EL LAVADO DE ACTIVOS DEL DECRETO LEGISLATIVO 1106, EL QUE PROPORCIONE A LAS AUTORIDADES INFORMACIÓN EFICAZ PARA DETECTAR:.', 'O INCAUTAR LOS ACTIVOS OBJETO DE LOS ACTOS DESCRITOS EN LOS ARTÍCULOS 1, 2 Y 3 DEL PRESENTE DECRETO LEGISLATIVO.', 'ART. 4 Tercer Párrafo', '185059'),
    (2373, 'SUB-2373', 'SBM4', 'CONSTITUYE OMISIÓN DE COMUNICACIÓN DE OPERACIONES O TRANSACCIONES SOSPECHOSAS; EL QUE:.', 'INCUMPLIENDO SUS OBLIGACIONES FUNCIONALES O PROFESIONALES, OMITE COMUNICAR A LA AUTORIDAD COMPETENTE, LAS TRANSACCIONES U OPERACIONES SOSPECHOSAS QUE HUBIERE DETECTADO, SEGÚN LAS LEYES Y NORMAS REGLAMENTARIAS.', 'ART. 5.', '185060'),
    (2374, 'SUB-2374', 'SBM4', 'COMETE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN, EL QUE:.', 'REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE LA INFORMACIÓN ECONÓMICA, FINANCIERA, CONTABLE, MERCANTIL O EMPRESARIAL.', 'ART. 6. Primer Párrafo', '185061'),
    (2375, 'SUB-2375', 'SBM4', 'CONSTITUYE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN EL QUE REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE; LA INFORMACIÓN:.', 'ECONÓMICA QUE LE SEA REQUERIDA, EN EL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR EL DELITO DE LAVADO DE ACTIVOS.', 'ART. 6. Primer Párrafo DL 1106 - Lucha contra el lavado de activos', '185062'),
    (2376, 'SUB-2376', 'SBM4', 'CONSTITUYE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN, EL QUE REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE; LA INFORMACIÓN:.', 'FINANCIERA, QUE LE SEA REQUERIDA, EN EL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR DELITO DE LAVADO DE ACTIVOS.', 'ART. 6. Primer Párrafo', '185063'),
    (2377, 'SUB-2377', 'SBM4', 'CONSTITUYE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN, EL QUE REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE; LA INFORMACIÓN:.', 'MERCANTIL, QUE LE SEA REQUERIDA, EN EL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR EL DELITO DE LAVADO DE ACTIVOS.', 'ART. 6. Primer Párrafo', '185065'),
    (2378, 'SUB-2378', 'SBM4', 'CONSTITUYE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN:.', 'EL QUE REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE LA INFORMACIÓN ECONOMICA, FINANCIERA, CONTABLE, MERCANTIL O EMPRESARIAL QUE LE SEA REQUERIDA.', 'ART. 6. Primer Párrafo', '185066'),
    (2379, 'SUB-2379', 'SBM4', 'CONSTITUYE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN EN EL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR DELITO DE LAVADO DE ACTIVOS EL QUE:.', 'DELIBERADAMENTE PRESTA LA INFORMACIÓN DE MODO INEXACTO O BRINDA INFORMACION FALSA.', 'ART. 6. Primer Párrafo', '185067'),
    (2380, 'SUB-2380', 'SBM4', 'EN EL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR DELITO DE LAVADO DE ACTIVOS; CONSTITUYE REHUSAMIENTO, RETARDO Y FALSEDAD EN EL SUMINISTRO DE INFORMACIÓN ; EL QUE:.', 'BRINDA INFORMACIÓN FALSA.', 'ART. 6. Primer Párrafo', '185068'),
    (2381, 'SUB-2381', 'SBM4', 'EL QUE REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE, INFORMACIÓN ECONÓMICA,FINANCIERA, CONTABLE, MERCANTIL O EMPRESARIAL DENTRO DEL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR DELITO DE LAVADO DE ACTIVOS; SE CONSIDERA AGRAVADO CUANDO SE VINCULA A:.', 'MINERIA ILEGAL.', 'ART. 6. Segundo Párrafo', '185069'),
    (2382, 'SUB-2382', 'SBM4', 'EL QUE REHÚSA O RETARDA SUMINISTRAR A LA AUTORIDAD COMPETENTE, INFORMACIÓN ECONÓMICA, FINANCIERA, CONTABLE, MERCANTIL O EMPRESARIAL EN EL MARCO DE UNA INVESTIGACIÓN O JUZGAMIENTO POR DELITO DE LAVADO DE ACTIVOS; SE CONSIDERA AGRAVADO CUANDO SE VINCULA A:.', 'CRIMEN ORGANIZADO.', 'ART. 6. Segundo Párrafo', '185070'),
    (2383, 'SUB-2383', 'SBM4', 'EL FISCAL PODRÁ SOLICITAR AL JUEZ EL LEVANTAMIENTO DEL SECRETO BANCARIO, EL SECRETO DE LAS COMUNICACIONES, LA RESERVA TRIBUTARIA Y LA RESERVA BURSATIL; CORRESPONDE A:.', 'REGLAS DE INVESTIGACIÓN.', 'ART. 7', '185073'),
    (2384, 'SUB-2384', 'SBM4', 'PARA LA INVESTIGACIÓN DE LOS DELITOS PREVISTOS EN EL PRESENTE DECRETO LEGISLATIVO, PODRÁ:.', 'EL FISCAL SOLICITAR AL JUEZ EL LEVANTAMIENTO DEL SECRETO BANCARIO, EL SECRETO DE LAS COMUNICACIONES, LA RESERVA TRIBUTARIA Y LA RESERVA BURSÁTIL.', 'ART. 7', '185074'),
    (2385, 'SUB-2385', 'SBM4', '¿QUIÉN SOLICITA AL JUEZ EL LEVANTAMIENTO DEL SECRETO BANCARIO, EL SECRETO DE LAS COMUNICACIONES, LA RESERVA TRIBUTARIA Y LA RESERVA BURSÁTIL?.', 'EL FISCAL.', 'ART. 7', '185075'),
    (2386, 'SUB-2386', 'SBM4', 'EL FISCAL PODRÁ SOLICITAR EL LEVANTAMIENTO DEL SECRETO BANCARIO, EL SECRETO DE LAS COMUNICACIONES, LA RESERVA TRIBUTARIA Y LA RESERVA BURSÁTIL AL:.', 'JUEZ', 'ART. 7', '185076'),
    (2387, 'SUB-2387', 'SBM4', 'PARA LA INVESTIGACIÓN DE LOS DELITOS PREVISTOS EN EL PRESENTE DECRETO LEGISLATIVO, EL FISCAL PODRÁ SOLICITAR:.', 'EL LEVANTAMIENTO DEL SECRETO BANCARIO, EL SECRETO DE LAS COMUNICACIONES, LA RESERVA TRIBUTARIA Y LA RESERVA BURSÁTIL.', 'ART. 7', '185077'),
    (2388, 'SUB-2388', 'SBM4', 'LA INFORMACIÓN OBTENIDA EN ESTOS CASOS POR EL LEVANTAMIENTO DEL SECRETO BANCARIO, EL SECRETO DE LAS COMUNICACIONES, LA RESERVA TRIBUTARIA Y LA RESERVA BURSÁTIL; SÓLO SERÁ UTILIZADA EN:.', 'RELACIÓN CON LA INVESTIGACIÓN DE LOS HECHOS QUE LA MOTIVARON.', 'ART. 7', '185078'),
    (2389, 'SUB-2389', 'SBM4', '¿EN TODOS LOS CASOS, QUIEN RESOLVERÁ LA INCAUTACIÓN O EL DECOMISO DEL DINERO, BIENES, EFECTOS O GANANCIAS INVOLUCRADOS, CONFORME A LO PREVISTO EN EL ARTÍCULO 102 DEL CÓDIGO PENAL?:.', 'EL JUEZ.', 'ART. 9', '185079'),
    (2390, 'SUB-2390', 'SBM4', 'INCURRE EN OMISIÓN DE COMUNICACIÓN DE OPERACIONES O TRANSACCIONES SOSPECHOSAS EL QUE INCUMPLE:.', 'SUS OBLIGACIONES FUNCIONALES O PROFESIONALES. DL 1106 - Lucha contra el lavado de activos', 'ART. 5. primer parrafo', '185081'),
    (2391, 'SUB-2391', 'SBM4', 'LA PENA SERÁ PRIVATIVA DE LA LIBERTAD NO MENOR DE DIEZ NI MAYOR DE VEINTE AÑOS Y TRESCIENTOS SESENTA Y CINCO A SETECIENTOS TREINTA DÍAS MULTA, CUANDO:.', 'EL AGENTE UTILICE O SE SIRVA DE SU CONDICIÓN DE FUNCIONARIO PÚBLICO.', 'ART. 4.1', '185082'),
    (2392, 'SUB-2392', 'SBM4', 'ES UNA FUNCIÓN Y FACULTAD DE LA UIF - PERÚ:.', 'SOLICITAR, RECIBIR, REQUERIR AMPLIACIONES Y ANALIZAR INFORMACIÓN SOBRE LAS OPERACIONES SOSPECHOSAS QUE LE REPORTEN LOS SUJETOS OBLIGADOS.', 'DISPOSICIONES COMPLEMENTARIAS MODIFICATORIAS', '185084'),
    (2393, 'SUB-2393', 'SBM4', 'ES UNA FUNCIÓN Y FACULTAD DE LA UIF - PERÚ:.', 'COMUNICAR AL MINISTERIO PÚBLICO AQUELLAS OPERACIONES QUE LUEGO DEL ANÁLISIS E INVESTIGACIÓN RESPECTIVOS, SE PRESUMA QUE ESTÉN VINCULADAS A ACTIVIDADES DE LAVADO DE ACTIVOS.', 'DISPOSICIONES COMPLEMENTARIAS MODIFICATORIAS', '185085'),
    (2394, 'SUB-2394', 'SBM4', 'EL LAVADO DE ACTIVOS ES UN DELITO AUTÓNOMO POR LO QUE PARA SU INVESTIGACIÓN, PROCESAMIENTO Y SANCIÓN:.', 'NO ES NECESARIO QUE LAS ACTIVIDADES CRIMINALES QUE PRODUJERON EL DINERO, LOS BIENES, EFECTOS O GANANCIAS HAYAN SIDO DESCUBIERTAS.', 'ART. 10 Primer Párrafo', '185086'),
    (2395, 'SUB-2395', 'SBM4', 'NO PODRÁN ACOGERSE A LOS BENEFICIOS PENITENCIARIOS DE REDENCIÓN DE LA PENA POR EL TRABAJO Y LA EDUCACIÓN:', 'EL AGENTE UTILICE O SE SIRVA DE SU CONDICIÓN DE FUNCIONARIO PÚBLICO O DE AGENTE DEL SECTOR INMOBILIARIO', 'ART. 4', '185087'),
    (2396, 'SUB-2396', 'SBM4', 'PUEDE EXCEPCIONALMENTE SOLICITAR LA INTERVENCIÓN DE LAS FUERZAS ARMADAS PARA LAS ACCIONES DE INTERDICCIÓN DE LA MINERÍA ILEGAL, LAVADO DE ACTIVOS U OTRAS FORMAS DE CRIMEN ORGANIZADO:.', 'EL FISCAL.', 'ART. 16', '185088'),
    (2397, 'SUB-2397', 'SBM4', 'CUANDO SE TRATE DE INVESTIGACIONES RELACIONADAS CON EL LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DE TERRORISMO, LA UIF:.', 'PRESTARÁ LA ASISTENCIA TÉCNICA QUE LE SEA REQUERIDA.', 'DISPOSICIONES COMPLEMENTARIAS MODIFICATORIAS', '185089'),
    (2398, 'SUB-2398', 'SBM4', 'A FIN DE LOGRAR UNA MAYOR EFICACIA EN LA LUCHA CONTRA EL DELITO DE LAVADO DE ACTIVOS, VINCULADO ESPECIALMENTE A LA MINERÍA ILEGAL U OTRAS FORMAS DE CRIMEN ORGANIZADO, LA UIF-PERÚ MANTENDRÁ RELACIONES DE COORDINACIÓN, CON:.', 'EL CONSEJO DE DEFENSA JURÍDICA DEL ESTADO.', 'DISPOSICIONES COMPLEMENTARIAS FINALES', '185090'),
    (2399, 'SUB-2399', 'SBM4', 'ES FUNCIÓN Y FACULTAD DE LA UIF - PERÚ SUPERVISAR Y SANCIONAR EN MATERIA DE PREVENCIÓN DEL DELITO DE LAVADO DE ACTIVOS Y EL FINANCIAMIENTO DE TERRORISMO A:.', 'A AQUELLOS SUJETOS OBLIGADOS QUE CARECEN DE ORGANISMO SUPERVISOR.', 'DISP. COMP.MOD. - PRIMERA', '185091'),
    (2400, 'SUB-2400', 'SBM4', 'LOS REGISTROS DE OPERACIONES A QUE HACE REFERENCIA EL ARTÍCULO 9 Ó CUALQUIER INFORMACIÓN RELACIONADA A ÉSTOS, DEBERÁN SER ENTREGADOS OBLIGATORIAMENTE POR LOS SUJETOS OBLIGADOS A LA UIF-PERÚ:.', 'POR EL MEDIO ELECTRÓNICO, PERIODICIDAD Y MODALIDAD QUE ÉSTA ESTABLEZCA.', 'DISP. COMP.MOD. - PRIMERA', '185092')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

